window.BOOK_DATA=window.BOOK_DATA||{};BOOK_DATA["ch01.ta"]={"id":"ch01","lang":"ta","title":"Function","titleTa":"செயற்கூறு","pages":[{"page":1,"steps":[{"say":"வணக்கம் மாணவர்களே! நான் குரு. இன்று பாடம் ஒன்று, செயற்கூறு (function) பற்றிக் கற்கப் போகிறோம். இந்தப் பாடத்தில் செயற்கூறு வரையறை, அளபுருக்கள், செயலுருபுகள், இடைமுகம், pure செயற்கூறு, பக்க விளைவுகள் ஆகியவற்றைப் பார்ப்போம். கவலைப்படாதீர்கள், எளிதாகக் கற்கலாம்.","board":[{"kind":"heading","title":"பாடம் 1: செயற்கூறு (Function)","body":""},{"kind":"point","title":"அளபுரு, செயலுருபு, இடைமுகம், pure, பக்க விளைவு","body":""}]},{"say":"ஒரு செயலைச் செய்து முடிக்கும் நேரம், நெறிமுறையை மதிப்பீடு செய்ய மிக முக்கியம். இந்த நேரம் நிரலாக்க மொழி, நிரல் பெயர்ப்பி, கணினி ஆகியவற்றைச் சார்ந்திருக்கக்கூடாது. சில கூற்றுகளை மீண்டும் மீண்டும் செய்ய வேண்டுமானால் துணை நிரல்கள் (subroutines) பயன்படுகின்றன.","board":[{"kind":"keyterm","title":"துணை நிரல் (Subroutine)","body":"ஒரு குறிப்பிட்ட செயலை மீண்டும் மீண்டும் செய்யப் பயன்படும் சிறிய நிரல் தொகுதி"}]},{"say":"நிரலாக்க மொழிகளில் துணை நிரல்களையே செயற்கூறுகள் என்று அழைக்கிறோம். செயற்கூறு என்பது ஒரு பெரிய நிரலில் வரையறுக்கப்படும் குறிமுறை அலகு. இது மாறிகள், கோவைகள் போன்ற உள்ளீடுகளைப் பெற்று நிலையான வெளியீட்டைத் தரும். இது தேர்வுக்கு முக்கியம்.","board":[{"kind":"keyterm","title":"செயற்கூறு (Function)","body":"பெரிய நிரலில் வரையறுக்கப்படும் குறிமுறை அலகு"}]},{"say":"இப்போது வரையறை. a இரட்டைப் புள்ளி சமம் அடைப்புக்குள் 24 என்பதில், 24 என்பது கோவை அல்ல. இது ஒரு வரையறை (definition). வரையறை ஒரு மதிப்பைப் பெயருடன் பிணைக்கிறது. இங்கே 24 என்ற மதிப்பு a என்ற பெயருடன் பிணைக்கப்படுகிறது. வரையறைகள் கோவைகள் அல்ல.","board":[{"kind":"code","title":"வரையறை","body":"a:=(24)"},{"kind":"warning","title":"வரையறை வேறு, கோவை வேறு","body":""}]},{"say":"அளபுருக்கள் (parameters) என்பவை செயற்கூறு வரையறையில் உள்ள மாறிகள். செயலுருபுகள் (arguments) என்பவை செயற்கூறுக்கு அனுப்பப்படும் மதிப்புகள். வகுப்பறையில் படிவத்தில் உள்ள காலி இடம் அளபுரு, அதில் நிரப்பும் பெயர் செயலுருபு என நினைக்கலாம்.","board":[{"kind":"keyterm","title":"அளபுரு (Parameter)","body":"செயற்கூறு வரையறையில் உள்ள மாறி"},{"kind":"keyterm","title":"செயலுருபு (Argument)","body":"செயற்கூறுக்கு அனுப்பப்படும் மதிப்பு"}]},{"say":"தரவு வகையைக் குறிப்பிடாமலும் எழுதலாம். சில நிரல் பெயர்ப்பிகள் அதை அனுமானிக்கும். தரவு வகை குறிப்புடன் எழுதினால் அடைப்புக்குறிகள் கட்டாயம். தற்சுழற்சி செயற்கூறுக்கு let rec பயன்படுத்த வேண்டும். தன்னைத் தானே அழைக்கும் செயற்கூறு தற்சுழற்சி செயற்கூறு.","board":[{"kind":"code","title":"தரவு வகையுடன்","body":"let rec pow (a: int) (b: int) : int :=\n    if b=0 then 1\n    else a * pow b (a-1)"},{"kind":"point","title":"வகை குறிப்புக்கு ( ) கட்டாயம்","body":""}]},{"say":"இடைமுகம் என்பது ஒரு பொருள் செய்யக்கூடிய செயல்களின் தொகுப்பு. அதை உண்மையில் செய்வது செயல்படுத்துதல். சுவிட்சை அழுத்தினால் விளக்கு எரிகிறது. எப்படி எரிகிறது என்று தெரிய வேண்டியதில்லை. சுவிட்ச் இடைமுகம், உள் இயக்கம் செயல்படுத்துதல்.","board":[{"kind":"keyterm","title":"இடைமுகம் vs செயல்படுத்துதல்","body":"இடைமுகம் செயலை வரையறுக்கும்; செயல்படுத்துதல் அதைச் செய்யும்"}]},{"say":"Pure செயற்கூறு என்பது ஒரே செயலுருபுகளுக்கு எப்போதும் ஒரே விடை தரும், பக்க விளைவு இல்லாதது. உதாரணம் square. Impure செயற்கூறு random போன்றது; விடை மாறும், வெளி மாறிகளை மாற்றும். இது ஐந்து மதிப்பெண் வினா.","board":[{"kind":"code","title":"Pure செயற்கூறு","body":"let square x:=\n return: x * x"},{"kind":"warning","title":"Impure: random(), date() - விடை மாறும்","body":""}]}],"explainAgain":[{"say":"செயற்கூறு என்பது ஒரு சமையல் இயந்திரம் போல. அரிசியைப் போட்டால் சோறு வரும். அதே அரிசி, அதே அளவு என்றால் எப்போதும் அதே சோறு. இதுவே pure செயற்கூறு.","board":[{"kind":"point","title":"உள்ளீடு → செயற்கூறு → வெளியீடு","body":""}]},{"say":"பள்ளியில் படிவம் நிரப்புவது போல. படிவத்தில் உள்ள கட்டம் அளபுரு. நீங்கள் எழுதும் பெயர் செயலுருபு. சுவிட்சை அழுத்துவது இடைமுகம். மின்சாரம் பாய்வது செயல்படுத்துதல். செயற்கூறு வெளியே உள்ள y போன்ற மாறியை மாற்றினால் அது பக்க விளைவு.","board":[{"kind":"point","title":"கட்டம் = அளபுரு; எழுதியது = செயலுருபு","body":""}]}],"example":[{"say":"ஒரு எடுத்துக்காட்டு பார்ப்போம். gcd செயற்கூறு b பூஜ்ஜியம் ஆகும் வரை, b மற்றும் a mod b உடன் தன்னையே அழைக்கும். b பூஜ்ஜியம் ஆனதும் a ஐத் திருப்பும். gcd 13 27 விடை 1. gcd 20536 7826 விடை 2. இது pure செயற்கூறு.","board":[{"kind":"code","title":"gcd - தற்சுழற்சி, pure","body":"let rec gcd a b :=\n if b <> 0 then gcd b (a mod b)\n else\n return a\n\ngcd 13 27\n1\ngcd 20536 7826\n2"}]}],"checkQuestion":{"question":"அளபுரு என்றால் என்ன? செயலுருபு என்றால் என்ன? இரண்டையும் வேறுபடுத்திக் கூறுங்கள்.","idealAnswer":"அளபுருக்கள் என்பவை செயற்கூறு வரையறையில் உள்ள மாறிகள். செயலுருபுகள் என்பவை செயற்கூறு வரையறைக்கு அனுப்பப்படும் மதிப்புகள்.","keywords":["அளபுரு","செயலுருபு","மாறி","மதிப்பு","parameter"]}},{"page":2,"steps":[{"say":"போன பக்கத்தில் செயற்கூறு (function) என்றால் என்ன என்று பார்த்தோம். இப்போது அதன் அளபுருக்கள் மற்றும் செயலுருபுக்களை விரிவாகப் பார்க்கலாம்.","board":[{"kind":"heading","title":"அளபுருக்கள் மற்றும் செயலுருபுக்கள்","body":""}]},{"say":"செயற்கூறு வரையறையில் உள்ள மாறிகள் அளபுருக்கள் (parameters) எனப்படும். செயற்கூறுக்கு அனுப்பப்படும் மதிப்புகள் செயலுருபுக்கள் (arguments) எனப்படும். இது தேர்வில் அடிக்கடி கேட்கப்படும்.","board":[{"kind":"keyterm","title":"அளபுரு (Parameter)","body":"செயற்கூறு வரையறையில் உள்ள மாறி"},{"kind":"keyterm","title":"செயலுருபு (Argument)","body":"செயற்கூறுக்கு அனுப்பப்படும் மதிப்பு"}]},{"say":"இந்த எடுத்துக்காட்டில் pow என்பது செயற்கூறின் பெயர். இது a-யின் b மடங்கு அடுக்கைத் திருப்பித் தர வேண்டும். requires என்பது முன் நிபந்தனை. b பூஜ்யத்தை விடக் குறையக்கூடாது. returns என்பது பின் நிபந்தனை, அதாவது திருப்பித் தரும் விடை.","board":[{"kind":"code","title":"தரவு வகை இல்லாத அளபுருக்கள்","body":"(requires: b>=0 )\n(returns: a to the power of b)\nlet rec pow a b:=\n    if b=0 then 1\n    else a * pow b (a-1)"}]},{"say":"இங்கே நாம் எந்தத் தரவு வகையையும் எழுதவில்லை. சில மொழிகளின் நிரல் பெயர்ப்பி (compiler) அதைத் தானே அனுமானிக்கும். சிலவற்றில் தரவு வகை எழுதுவது கட்டாயம்.","board":[{"kind":"point","title":"தரவு வகை எழுதாவிட்டால் நிரல் பெயர்ப்பி அனுமானிக்கும்","body":""}]},{"say":"அனுமானம் எப்படி நடக்கிறது? if கோவையின் then பகுதி 1 என்ற முழு எண்ணைத் தருகிறது. எனவே if கோவை முழுவதும் int வகை. அதனால் செயற்கூறு திருப்பும் மதிப்பும் int. b பூஜ்யத்துடன் ஒப்பிடப்படுவதால் b int ஆகும். a பெருக்கலில் பயன்படுவதால் a-வும் int ஆகும்.","board":[{"kind":"point","title":"a, b மற்றும் திருப்பும் மதிப்பு மூன்றும் int","body":""}]},{"say":"இப்போது அதே செயற்கூறை தரவு வகையுடன் எழுதலாம். இதை type annotation என்பர். இங்கே அடைப்புக்குறிகள் அவசியம். இது தேர்வில் முக்கியம்.","board":[{"kind":"code","title":"தரவு வகையுடன் கூடிய அளபுருக்கள்","body":"(requires: b> = 0 )\n(returns: a to the power of b )\nlet rec pow (a: int) (b: int) : int :=\n    if b=0 then 1\n    else a * pow b (a-1)"},{"kind":"warning","title":"தரவு வகை குறிப்புக்கு ( ) அடைப்புக்குறி கட்டாயம்","body":""}]},{"say":"தரவு வகை எழுதுவது பிழைச் செய்தியைப் புரிந்து திருத்த உதவும். வரையறை let என்ற சிறப்புச் சொல்லுடன் தொடங்கும். பிறகு செயற்கூறின் பெயர், அளபுருக்கள், அதன் பின் := குறி, பிறகு கணக்கீடு. தன்னைத் தானே அழைக்கும் தற்சுழற்சி (recursive) செயற்கூறுக்கு let rec எழுத வேண்டும்.","board":[{"kind":"code","title":"தொடரியல்","body":"let rec fn a1 a2 ... an := k"},{"kind":"point","title":"fn பெயர்; a1 முதல் an வரை அளபுருக்கள்; rec = தற்சுழற்சி","body":""}]}],"explainAgain":[{"say":"ஒரு எளிய உவமை பார்க்கலாம். பள்ளி உணவகத்தில் டோக்கன் படிவம் இருக்கிறது என்று வைத்துக்கொள்ளுங்கள். படிவத்தில் உள்ள காலி கட்டம் தான் அளபுரு.","board":[{"kind":"point","title":"காலி கட்டம் = அளபுரு","body":""}]},{"say":"நீங்கள் அந்தக் கட்டத்தில் எழுதும் உண்மையான பெயர் அல்லது எண் தான் செயலுருபு. படிவம் ஒன்றே, ஆனால் ஒவ்வொரு முறையும் நிரப்பும் மதிப்பு மாறும்.","board":[{"kind":"point","title":"நிரப்பும் மதிப்பு = செயலுருபு","body":""}]}],"example":[{"say":"ஒரு எடுத்துக்காட்டு பார்க்கலாம். இங்கே x மற்றும் y அளபுருக்கள். செயற்கூறை add 3 4 என அழைத்தால் 3 மற்றும் 4 செயலுருபுக்கள். x-க்கு 3-ம், y-க்கு 4-ம் செல்கிறது. விடை 7.","board":[{"kind":"code","title":"அளபுரு மற்றும் செயலுருபு","body":"let add (x: int) (y: int) : int :=\n    x + y\n\nadd 3 4\n7"}]}],"checkQuestion":{"question":"அளபுரு என்றால் என்ன? செயலுருபு என்றால் என்ன? இரண்டையும் வேறுபடுத்திக் கூறுங்கள்.","idealAnswer":"செயற்கூறு வரையறையில் உள்ள மாறிகள் அளபுருக்கள் (parameters). செயற்கூறை அழைக்கும்போது அதற்கு அனுப்பப்படும் மதிப்புகள் செயலுருபுக்கள் (arguments).","keywords":["அளபுரு","செயலுருபு","மாறி","மதிப்பு","parameter"]}},{"page":3,"steps":[{"say":"முந்தைய பக்கத்தில் அளபுருக்கள் (parameters), செயலுருபுகள் (arguments) மற்றும் pow செயற்கூறு வரையறையைப் பார்த்தோம். இப்போது தற்சுழற்சி செயற்கூறு பற்றிப் பார்க்கலாம்.","board":[{"kind":"heading","title":"தற்சுழற்சி செயற்கூறு (Recursive function)","body":""}]},{"say":"தன்னைத் தானே அழைத்துக் கொள்ளும் செயற்கூறு வரையறைக்கு தற்சுழற்சி செயற்கூறு என்று பெயர். இதை வரையறுக்க let என்பதற்குப் பதிலாக let rec என்று எழுத வேண்டும். இது தேர்வுக்கு முக்கியம்.","board":[{"kind":"keyterm","title":"தற்சுழற்சி செயற்கூறு","body":"தன்னைத் தானே அழைத்துக் கொள்ளும் செயற்கூறு. let rec பயன்படுத்தப்படும்."}]},{"say":"எடுத்துக்காட்டாக, factorial கணக்கிடும் செயற்கூறைப் பாருங்கள். இதற்கு முன் நிபந்தனை, n பூஜ்ஜியத்தை விடப் பெரியது அல்லது சமம் என்பதாகும். n பூஜ்ஜியம் எனில் விடை ஒன்று. இல்லையெனில் n என்பதை, n கழித்தல் ஒன்றின் factorial உடன் பெருக்க வேண்டும்.","board":[{"kind":"code","title":"Factorial","body":"(Requires: n>= 0)\nlet rec fact n :=\n    if n = 0 then 1\n    else\n        n * fact(n-1)"}]},{"say":"அடுத்து செயற்கூறு வகைகளின் தொடரியல். x அம்புக்குறி y என்றால், x வகை உள்ளீட்டைப் பெற்று y வகை வெளியீட்டைத் தரும்.","board":[{"kind":"code","title":"செயற்கூறு வகைகள்","body":"x → y\nx1 → x2 → y\nx1 → ... → xn → y"}]},{"say":"x1 அம்புக்குறி x2 அம்புக்குறி y என்றால், இரண்டு உள்ளீடுகள். முதலாவது x1 வகை, இரண்டாவது x2 வகை. வெளியீடு y வகை. இதே போல் n அளபுருக்களுக்கும் எழுதலாம். கடைசி வகையே எப்போதும் வெளியீட்டு வகை.","board":[{"kind":"point","title":"கடைசி வகை = வெளியீட்டு வகை","body":""}]},{"say":"ஒரு முக்கிய குறிப்பு. அனைத்து செயற்கூறுகளும் நிலையான (static) வரையறைகளே. மாறும் செயற்கூறு வரையறை (dynamic function definition) என்பது இல்லை.","board":[{"kind":"warning","title":"Dynamic function definition இல்லை; அனைத்தும் static","body":""}]},{"say":"இப்போது இடைமுகம் (Interface) பகுதி. ஒரு பொருள் செய்யக்கூடிய செயல்களின் தொகுப்பே இடைமுகம். மின்விளக்கு சுவிட்சை அழுத்தினால் விளக்கு எரிகிறது. எப்படி எரிகிறது என்று தெரிய வேண்டியதில்லை. அதற்கு turn_on மற்றும் turn_off செயற்கூறுகள் இருக்கும்.","board":[{"kind":"keyterm","title":"இடைமுகம் (Interface)","body":"பொருள் செய்யக்கூடிய செயல்களை வரையறுக்கும்; ஆனால் அவற்றை உண்மையில் செய்யாது."},{"kind":"keyterm","title":"செயல்படுத்துதல் (Implementation)","body":"இடைமுகத்தில் வரையறுத்த கட்டளைகளை நிறைவேற்றும்."}]}],"explainAgain":[{"say":"தற்சுழற்சியை ஒரு எளிய உதாரணத்தால் பார்க்கலாம். வகுப்பில் வரிசையில் நிற்கும் மாணவர்களிடம் நீங்கள் எத்தனாவது இடம் என்று கேட்கிறீர்கள். ஒவ்வொருவரும் தனக்கு முன்னால் இருப்பவரிடம் அதே கேள்வியைக் கேட்கிறார்கள். முதல் மாணவர் ஒன்று என்று சொன்னதும் பதில் பின்னோக்கி வருகிறது.","board":[{"kind":"point","title":"தன்னைப் போன்ற சிறிய கேள்வியை மீண்டும் கேட்பது","body":""}]},{"say":"அந்த முதல் மாணவர்தான் நிறுத்தும் நிபந்தனை. factorial இல் n பூஜ்ஜியம் என்றால் ஒன்று என்பதே அது. இது இல்லையெனில் செயற்கூறு முடிவே இல்லாமல் ஓடும்.","board":[{"kind":"warning","title":"நிறுத்தும் நிபந்தனை அவசியம்","body":""}]},{"say":"இடைமுகத்தை வகுப்பறை மணி போல நினைக்கலாம். நீங்கள் பொத்தானை அழுத்துகிறீர்கள். உள்ளே மின் இணைப்பு எப்படி வேலை செய்கிறது என்பது செயல்படுத்துதல்.","board":[]}],"example":[{"say":"fact 3 இன் செயல்பாட்டைப் பார்ப்போம். fact 3 என்பது 3 பெருக்கல் fact 2. fact 2 என்பது 2 பெருக்கல் fact 1. fact 1 என்பது 1 பெருக்கல் fact 0. fact 0 இன் மதிப்பு 1. திரும்பும்போது 1, பிறகு 1, பிறகு 2, இறுதியில் 6 கிடைக்கும்.","board":[{"kind":"example","title":"fact 3 = 3 * 2 * 1 * 1 = 6","body":""},{"kind":"diagram","title":"அழைப்பு வரிசை","body":"flowchart TD\nA[\"fact 3\"] --> B[\"3 * fact 2\"]\nB --> C[\"2 * fact 1\"]\nC --> D[\"1 * fact 0\"]\nD --> E[\"fact 0 = 1\"]\nE --> F[\"விடை 6\"]"}]}],"checkQuestion":{"question":"தற்சுழற்சி செயற்கூறு என்றால் என்ன? அதை வரையறுக்க எந்தச் சிறப்புச் சொல்லைப் பயன்படுத்த வேண்டும்?","idealAnswer":"தன்னைத் தானே அழைத்துக் கொள்ளும் செயற்கூறு வரையறைக்கு தற்சுழற்சி செயற்கூறு என்று பெயர். அதை வரையறுக்க let rec என்ற சிறப்புச் சொல்லைப் பயன்படுத்த வேண்டும்.","keywords":["தன்னைத் தானே","தற்சுழற்சி","recursive","let rec","rec"]}},{"page":4,"steps":[{"say":"போன பக்கத்தில் இடைமுகம் (interface) மற்றும் செயல்படுத்துதல் (implementation) என்ற இரண்டு சொற்களின் வேறுபாட்டைப் பார்த்தோம். இப்போது அதையே இன்னும் ஆழமாகப் பார்ப்போம்.","board":[{"kind":"heading","title":"இடைமுகம் மற்றும் pure செயற்கூறுகள்","body":""}]},{"say":"பொருள் நோக்கு நிரலாக்க மொழியில் இனக்குழு (class) என்பது இடைமுகம் ஆகும். செயல்படுத்துதல் என்பது பொருள் (object) உள்ளே எப்படி இயங்குகிறது என்பதைக் குறிக்கும்.","board":[{"kind":"keyterm","title":"இடைமுகம் (Interface)","body":"பொருள் என்ன செய்யலாம் என்பதை மட்டும் சொல்கிறது"},{"kind":"keyterm","title":"செயல்படுத்துதல் (Implementation)","body":"அது எப்படிச் செய்யப்படுகிறது என்பதைக் குறிக்கிறது"}]},{"say":"இடைமுகத்தின் பண்புகள் இரண்டு. ஒன்று, இனக்குழு வார்ப்புரு பொருளை உருவாக்கவும் பயன்படுத்தவும் தேவையான இடைமுகத்தைக் குறிப்பிடுகிறது. இரண்டு, செயற்கூறுகளைப் பொருளுக்கு அனுப்புவதன் மூலம் பொருளின் பண்புகளைக் கட்டுப்படுத்தலாம். இது தேர்வுக்கு முக்கியம்.","board":[{"kind":"point","title":"வார்ப்புரு தேவையான இடைமுகத்தைக் குறிப்பிடும்","body":""},{"kind":"point","title":"செயற்கூறுகள் மூலம் பொருளைக் கட்டுப்படுத்தலாம்","body":""}]},{"say":"காரின் எடுத்துக்காட்டைப் பாருங்கள். ஓட்டுநர் துரிதப்படுத்தியை (accelerator) அழுத்துகிறார். அதுவே இடைமுகம். இயந்திரம் எரிபொருள், காற்று, மின்சாரம் கொண்டு உள்ளே வேலை செய்வது செயல்படுத்துதல். ஓட்டுநருக்கு உள்ளே நடப்பது தெரிய வேண்டியதில்லை.","board":[{"kind":"diagram","title":"கார் எடுத்துக்காட்டு","body":"flowchart TD\nA[\"ஓட்டுநர்: speed(70)\"] --> B[\"Accelerator (இடைமுகம்)\"]\nB --> C[\"Engine (செயல்படுத்துதல்)\"]\nC --> D[\"கார் வேகமாகும்\"]"}]},{"say":"அடுத்து மூன்று எண்களில் சிறிய எண்ணைக் காணும் min செயற்கூறு. x, y ஐ ஒப்பிடுகிறோம். x சிறியதெனில் அதை z உடன் ஒப்பிடுகிறோம். இல்லையெனில் y ஐ z உடன் ஒப்பிட்டுச் சிறியதைத் தருகிறோம்.","board":[{"kind":"code","title":"min செயற்கூறு","body":"let min x y z :=\n if x < y then\n  if x < z then x else z\n else\n  if y < z then y else z"}]},{"say":"இப்போது pure செயற்கூறு (pure function). ஒரே செயலுருபுகளுக்கு எப்போதும் ஒரே விடை தரும் செயற்கூறு pure செயற்கூறு. எடுத்துக்காட்டாக, sin(0) எப்போதும் 0. வெளிப்புற மாறியை மாற்றாது.","board":[{"kind":"keyterm","title":"Pure செயற்கூறு","body":"அதே உள்ளீடு, எப்போதும் அதே வெளியீடு; பக்க விளைவு இல்லை"}]},{"say":"square செயற்கூறு pure ஆகும். ஏனெனில் x ஐ x ஆல் பெருக்கி மட்டும் தருகிறது. ஒரே உள்ளீட்டுக்கு வேறு விடை தராது.","board":[{"kind":"code","title":"square","body":"let square x:=\n return: x * x"}]},{"say":"pure செயற்கூறின் நன்மை, அதே செயலுருபுகளுடன் பலமுறை அழைத்தாலும், நிரல்பெயர்ப்பி (compiler) ஒரு முறை மட்டும் மதிப்பிட்டால் போதும். strlen இதற்கு உதாரணம். அது ஒரு மாறியை எடுத்து நீளத்தைக் கணக்கிடுகிறது, மதிப்புகளை மாற்றுவதில்லை. எனவே pure. pure செயற்கூறில் பக்க விளைவு ஏற்படாது என்பதை நினைவில் கொள்ளுங்கள்.","board":[{"kind":"warning","title":"Pure செயற்கூறுக்கு பக்க விளைவு (side effect) இல்லை","body":""}]}],"explainAgain":[{"say":"டீக்கடையை நினைத்துப் பாருங்கள். நீங்கள் டீ என்று சொல்கிறீர்கள். அது இடைமுகம். டீ எப்படிப் போடப்படுகிறது என்பது செயல்படுத்துதல். அது உங்களுக்குத் தெரிய வேண்டியதில்லை.","board":[{"kind":"point","title":"சொல்வது = இடைமுகம்; உள்ளே நடப்பது = செயல்படுத்துதல்","body":""}]},{"say":"pure செயற்கூறு கால்குலேட்டர் போன்றது. இரண்டும் இரண்டும் எப்போதும் நான்கு தான். random செயற்கூறு பகடை போன்றது, ஒவ்வொரு முறையும் வேறு விடை வரும்.","board":[{"kind":"point","title":"Pure = கால்குலேட்டர்; random = பகடை","body":""}]}],"example":[{"say":"ஒரு எடுத்துக்காட்டு. min 7 3 5 என அழைத்தால், 7 சிறியதா 3 ஐ விட என்று பார்க்கிறோம், இல்லை. எனவே y மற்றும் z ஆன 3 மற்றும் 5 ஐ ஒப்பிடுகிறோம். 3 சிறியது, எனவே விடை 3. எத்தனை முறை அழைத்தாலும் விடை 3 தான், எனவே இது pure.","board":[{"kind":"example","title":"min 7 3 5 → 3","body":"x<y? 7<3 இல்லை; y<z? 3<5 ஆம்; விடை 3"}]}],"checkQuestion":{"question":"pure செயற்கூறு என்றால் என்ன? ஓர் எடுத்துக்காட்டு சொல்லுங்கள்.","idealAnswer":"ஒரே மாதிரியான செயலுருபுகளை அனுப்பும்போது எப்போதும் ஒரே விடையைத் தரும், பக்க விளைவுகள் இல்லாத செயற்கூறு pure செயற்கூறு. எடுத்துக்காட்டு: sin(0) அல்லது square.","keywords":["pure","ஒரே விடை","பக்க விளைவு","செயலுருபு","square"]}},{"page":5,"steps":[{"say":"போன பக்கத்தில் pure செயற்கூறு என்றால், ஒரே செயலுருபுகளுக்கு எப்போதும் ஒரே விடை தரும் செயற்கூறு என்று பார்த்தோம். இந்தப் பக்கத்தில் pure செயற்கூறின் நன்மையையும், impure செயற்கூறையும் பார்க்கலாம்.","board":[{"kind":"heading","title":"Pure செயற்கூறின் நன்மை மற்றும் Impure செயற்கூறு","body":""}]},{"say":"pure செயற்கூறுக்கு கோட்பாடு சார்ந்த நன்மைகள் உள்ளன. ஒரு நன்மை என்னவென்றால், அதே அளபுருக்களுடன் பலமுறை அழைத்தாலும், நிரல்பெயர்ப்பி (compiler) செயற்கூறை ஒரே ஒரு முறை மட்டும் அழைத்தால் போதும்.","board":[{"kind":"point","title":"அதே அளபுருக்கள் என்றால் ஒரு முறை அழைத்தால் போதும்","body":""}]},{"say":"புத்தகத்தில் length என்ற செயற்கூறு உள்ளது. அதில் i என்ற மாறி சுழியத்தில் தொடங்குகிறது. i ஆனது strlen of s ஐ விடக் குறைவாக இருக்கும் வரை சுழற்சி நடக்கிறது. ஒவ்வொரு முறையும் strlen அழைக்கப்படுகிறது.","board":[{"kind":"code","title":"length செயற்கூறு","body":"let length s:=\n    i: = 0\n    if i <strlen (s) then\n    -- Do something which doesn't affect s\n    ++i"}]},{"say":"strlen ஒவ்வொரு முறையும் முழு s ஐயும் சுற்றிப் பார்க்க வேண்டும். strlen pure செயற்கூறு என்பதாலும், சுழற்சிக்குள் s மாறாது என்பதாலும், தேவையற்ற அழைப்புகளை நீக்கி strlen ஐ ஒரே முறை மட்டும் அழைக்கலாம். இதனால் நிரல் வேகமாக ஓடும்.","board":[{"kind":"point","title":"strlen pure என்பதால் தேவையற்ற அழைப்புகளை நீக்கலாம்","body":""}]},{"say":"strlen ஏன் pure? ஏனெனில் அது ஒரே ஒரு மாறியை அளபுருவாக எடுத்து அதன் நீளத்தைக் கணக்கிடுகிறது. வெளி நினைவகத்திலிருந்து உள்ளீட்டை எடுக்கும், ஆனால் மதிப்புகளை மாற்றாது. இது தேர்வில் மூன்று மதிப்பெண் கேள்வியாக வரும்.","board":[{"kind":"warning","title":"தேர்வு: strlen ஏன் pure செயற்கூறு?","body":""}]},{"say":"முக்கியக் குறிப்பு: pure செயற்கூறை மதிப்பீடு செய்யும்போது எந்த பக்க விளைவும் (side effect) ஏற்படாது.","board":[{"kind":"keyterm","title":"Pure செயற்கூறு","body":"பக்க விளைவு இல்லை; ஒரே உள்ளீடு, ஒரே வெளியீடு"}]},{"say":"இப்போது impure செயற்கூறு. செயற்கூறு வரையறைக்கு வெளியே உள்ள மாறிகள் அல்லது செயற்கூறுகளைச் சார்ந்தால், ஒவ்வொரு முறையும் ஒரே மாதிரி இயங்கும் என்று சொல்ல முடியாது. இதை impure செயற்கூறு (impure function) என்பர்.","board":[{"kind":"keyterm","title":"Impure செயற்கூறு","body":"வெளி மாறிகளைச் சார்ந்தது; பக்க விளைவுகளை ஏற்படுத்தும்"}]},{"say":"எடுத்துக்காட்டாக random செயற்கூறு. ஒரே மாதிரி அழைத்தாலும் வெவ்வேறு விடை தரும். புத்தகத்தில் a ஆனது random மதிப்பு. a பத்தை விடப் பெரியதெனில் a திரும்பும், இல்லையெனில் பத்து திரும்பும். random impure ஆகும், ஏனெனில் என்ன விடை வரும் என்று உறுதியாகச் சொல்ல முடியாது.","board":[{"kind":"code","title":"Impure எடுத்துக்காட்டு","body":"let a:= random()\n    if a > 10 then\n        return: a\n    else\n        return: 10"}]}],"explainAgain":[{"say":"ஒரு கணிதத் தேர்வில் இரண்டும் இரண்டும் எப்போதும் நான்கு. யார் கேட்டாலும், எத்தனை முறை கேட்டாலும் அதே விடை. இது pure செயற்கூறு போன்றது.","board":[{"kind":"point","title":"Pure: 2 + 2 எப்போதும் 4","body":""}]},{"say":"ஆனால் பகல் உணவு இடைவேளையில் இன்று என்ன சாப்பாடு என்று கேட்டால், நாளுக்கு நாள் மாறும். இது impure செயற்கூறு போன்றது. இது random மற்றும் date போல.","board":[{"kind":"point","title":"Impure: ஒவ்வொரு முறையும் வேறு விடை (random, date)","body":""}]},{"say":"pure என்றால் முன்பே விடை தெரியும், அதனால் மீண்டும் மீண்டும் கணக்கிட வேண்டாம். நினைவில் வைத்தால் நேரம் மிச்சம்.","board":[]}],"example":[{"say":"ஒரு எடுத்துக்காட்டு பார்க்கலாம். square செயற்கூறு x ஐ x ஆல் பெருக்கும். square of 5 எப்போதும் 25. எனவே இது pure. நிரல்பெயர்ப்பி ஒரு முறை கணக்கிட்டு விடையை மீண்டும் பயன்படுத்தலாம்.","board":[{"kind":"example","title":"square 5 → எப்போதும் 25 (pure)","body":"let square x:=\n return: x * x"}]},{"say":"ஆனால் random அழைப்பு இன்று 7, நாளை 42 தரலாம். எனவே அதை impure என்கிறோம்.","board":[{"kind":"example","title":"random() → ஒவ்வொரு முறையும் வேறு (impure)","body":""}]}],"checkQuestion":{"question":"strlen ஏன் pure செயற்கூறு என்று அழைக்கப்படுகிறது? சொல்லுங்கள்.","idealAnswer":"strlen ஒரே ஒரு மாறியை அளபுருவாக எடுத்து அதன் நீளத்தைக் கணக்கிடுகிறது. அது மதிப்புகளை மாற்றாது, பக்க விளைவும் இல்லை. ஒரே உள்ளீட்டுக்கு எப்போதும் ஒரே விடை தரும். அதனால் அது pure செயற்கூறு.","keywords":["pure","பக்க விளைவு","side effect","ஒரே விடை","நீளம்"]}},{"page":6,"steps":[{"say":"முந்தைய பக்கத்தில் pure செயற்கூறு, impure செயற்கூறு மற்றும் பக்க விளைவுகள் (side effects) பற்றிப் பார்த்தோம். இப்போது அதற்கான எடுத்துக்காட்டைப் பார்ப்போம்.","board":[{"kind":"heading","title":"பக்க விளைவு மற்றும் Pure vs Impure","body":""}]},{"say":"இங்கே y என்ற மாறி செயற்கூறுக்கு வெளியே உள்ளது. அதன் தொடக்க மதிப்பு 0. inc என்ற செயற்கூறு x மதிப்பை y உடன் கூட்டி, y-ஐ மாற்றி, அதைத் திருப்பி அனுப்புகிறது.","board":[{"kind":"code","title":"inc செயற்கூறு","body":"y: = 0\nlet inc (x: int): int: =\n y: = y + x\nreturn (y)"}]},{"say":"இந்தச் செயற்கூறை ஒவ்வொரு முறை அழைக்கும்போதும் y மாறுகிறது. அதனால் அதே செயலுருபுக்கு வெவ்வேறு விடை கிடைக்கும். வெளிப்புற மாறி y-ன் மதிப்பை மாற்றுவதே inc-ன் பக்க விளைவு.","board":[{"kind":"keyterm","title":"பக்க விளைவு (side effect)","body":"செயற்கூறுக்கு வெளியே உள்ள மாறியை மாற்றுவது"}]},{"say":"சில பக்க விளைவுகளை எளிதில் கண்டுபிடிக்கலாம். சிலவற்றை நன்கு யோசித்தே அறிய வேண்டும். பக்க விளைவு எப்போதும் கேடு அல்ல. சில நேரங்களில் பயனுள்ளது.","board":[{"kind":"warning","title":"பக்க விளைவு எப்போதும் கெட்டது அல்ல","body":""}]},{"say":"இப்போது வேறுபாடு. Pure செயற்கூறின் விடை செயலுருபுகளை மட்டுமே சார்ந்தது. அதே செயலுருபுக்கு எப்போதும் அதே விடை. பக்க விளைவு இல்லை. Impure செயற்கூறில் அதே செயலுருபுக்கு வெவ்வேறு விடை வரலாம். எடுத்துக்காட்டு random மற்றும் date. இது செயலுருபுகளை மாற்றவும் கூடும். இது தேர்வுக்கு மிக முக்கியம்.","board":[{"kind":"point","title":"Pure: அதே உள்ளீடு, அதே வெளியீடு, பக்க விளைவு இல்லை","body":""},{"kind":"point","title":"Impure: வெவ்வேறு வெளியீடு, எ.கா. random(), date()","body":""}]},{"say":"அடுத்து மீப்பெரு வகுஎண் காணும் pure செயற்கூறு gcd. b சுழியம் இல்லையெனில், b மற்றும் a mod b என்ற இரண்டு மதிப்புகளுடன் தன்னையே அழைக்கும். b சுழியமானால் a-ஐத் திருப்பும்.","board":[{"kind":"code","title":"gcd செயற்கூறு","body":"let rec gcd a b :=\n if b <> 0 then gcd b (a mod b)\n else\n return a"}]},{"say":"வெளியீடு: gcd 13 27 என்றால் 1. gcd 20536 7826 என்றால் 2. இது தற்சுழற்சி செயற்கூறு (recursive function) என்பதால் let rec பயன்படுத்தப்பட்டது.","board":[{"kind":"example","title":"gcd 13 27 → 1 ; gcd 20536 7826 → 2","body":""}]}],"explainAgain":[{"say":"ஒரு எளிய ஒப்புமை பார்ப்போம். Pure செயற்கூறு என்பது கால்குலேட்டர் போல. 5 ஐ இருமுறை பெருக்கினால் எப்போதும் 25 தான் வரும்.","board":[{"kind":"point","title":"Pure = கால்குலேட்டர்: அதே உள்ளீடு, அதே விடை","body":""}]},{"say":"Impure செயற்கூறு என்பது பள்ளி உண்டியல் போல. ஒவ்வொரு முறை 10 ரூபாய் போடும்போதும் மொத்தத் தொகை மாறுகிறது. இங்கே y என்பது உண்டியல், inc செயற்கூறு அதை மாற்றுகிறது. இதுவே பக்க விளைவு.","board":[{"kind":"point","title":"Impure = உண்டியல்: வெளியே உள்ள y மாறுகிறது","body":""}]}],"example":[{"say":"inc செயற்கூறில் y தொடக்கத்தில் 0 என்று எடுப்போம். inc 5 அழைத்தால் y என்பது 0 கூட்டல் 5, அதாவது 5. மீண்டும் inc 5 அழைத்தால் y என்பது 5 கூட்டல் 5, அதாவது 10. செயலுருபு அதே 5 ஆனாலும் விடை வேறு. எனவே இது impure செயற்கூறு.","board":[{"kind":"example","title":"y=0: inc 5 → 5 ; மீண்டும் inc 5 → 10","body":""}]}],"checkQuestion":{"question":"inc செயற்கூறின் பக்க விளைவு என்ன? அது ஏன் impure செயற்கூறு?","idealAnswer":"inc செயற்கூறு செயற்கூறுக்கு வெளியே உள்ள மாறி y-ன் மதிப்பை மாற்றுகிறது. இதுவே பக்க விளைவு. அதே செயலுருபுக்கு ஒவ்வொரு முறையும் வெவ்வேறு விடை தருவதால் இது impure செயற்கூறு.","keywords":["y","வெளிப்புற மாறி","பக்க விளைவு","side effect","impure","வெவ்வேறு விடை"]}},{"page":7,"steps":[{"say":"முந்தைய பக்கத்தில் pure மற்றும் impure செயற்கூறுகளையும், gcd எடுத்துக்காட்டையும் பார்த்தோம். இப்போது அதே செயற்கூறு கருத்தைப் பயன்படுத்தி, குரோமிலேண்டில் பச்சோந்திகள் சிக்கலைத் தீர்ப்போம்.","board":[{"kind":"heading","title":"செயற்கூறால் பச்சோந்திகள் சிக்கல்","body":""}]},{"say":"மூன்று வகை பச்சோந்திகளின் எண்ணிக்கை a, b, c. தொடக்க மதிப்புகள் முறையே A, B, C. உள்ளீட்டு பண்பு a சமம் b ஆகும். அதாவது முதல் இரண்டு வகையும் சம எண்ணிக்கையில் உள்ளன.","board":[{"kind":"keyterm","title":"உள்ளீடு (Input)","body":"a = A, b = B, c = C, a = b"}]},{"say":"முடிவில் எல்லா பச்சோந்திகளும் ஒரே நிறத்தில் இருக்க வேண்டும். அதாவது a மற்றும் b சுழியம் ஆக வேண்டும். c என்பது A கூட்டல் B கூட்டல் C ஆக இருக்கும். இந்த நெறிமுறைக்கு monochromatize என்று பெயர்.","board":[{"kind":"keyterm","title":"வெளியீடு (Output)","body":"a = b = 0, c = A+B+C"}]},{"say":"ஒவ்வொரு சுழற்சியிலும் ஒரே எண்ணிக்கையுள்ள இரண்டு வகை பச்சோந்திகள் சந்திக்கின்றன. அவை மூன்றாவது வகையின் நிறத்துக்கு மாறுகின்றன. அதனால் a மற்றும் b ஒவ்வொன்றும் ஒன்று குறையும். c இரண்டு கூடும்.","board":[{"kind":"point","title":"a ஒன்று குறையும், b ஒன்று குறையும், c இரண்டு கூடும்","body":""}]},{"say":"எடுத்துக்காட்டாக 4, 4, 6 எனத் தொடங்கினால், அடுத்து 3, 3, 8 ஆகும். பிறகு 2, 2, 10, பிறகு 1, 1, 12. கடைசியாக 0, 0, 14 ஆகும். a சுழியமானதும் நிறுத்துகிறோம்.","board":[{"kind":"example","title":"4,4,6 → 3,3,8 → 2,2,10 → 1,1,12 → 0,0,14","body":""}]},{"say":"பாய்வுப்படம் இப்படி: உள்ளீடு எடுக்கவும். a பூஜ்யத்தை விட பெரிதா எனப் பார்க்கவும். ஆம் எனில் மதிப்புகளை மாற்றி மீண்டும் சோதிக்கவும். இல்லை எனில் வெளியீடு தரவும்.","board":[{"kind":"diagram","title":"monochromatize பாய்வுப்படம்","body":"flowchart TD\nA[\"உள்ளீடு a, b, c\"] --> B{\"a > 0 ?\"}\nB -->|\"True\"| C[\"a, b, c := a-1, b-1, c+2\"]\nC --> B\nB -->|\"False\"| D[\"வெளியீடு a, b, c\"]"}]},{"say":"இதே நெறிமுறையைச் செயற்கூறாக எழுதியுள்ளனர். இது let rec எனத் தொடங்குவதால் தற்சுழற்சி செயற்கூறு. நிபந்தனை சரி எனில் மதிப்புகள் மாறும். பிறகு a, b, c திருப்பி அனுப்பப்படும். இந்த நிரலை நூலில் உள்ளபடியே எழுதப் பழகுங்கள். தேர்வுக்கு உதவும்.","board":[{"kind":"code","title":"monochromatize செயற்கூறு","body":"let rec monochromatize a b c :=\n    if a > 0 then\n        a, b, c := a-1, b-1, c+2\n    else\n        monochromatize a b c\n    return a, b, c"}]}],"explainAgain":[{"say":"பள்ளியில் இரண்டு நண்பர்கள் ஒவ்வொருவரும் ஒரு மிட்டாய் கொடுத்து, மூன்றாவது நண்பருக்கு இரண்டு மிட்டாய் சேர்க்கிறார்கள் என்று நினைத்துக் கொள்ளுங்கள்.","board":[{"kind":"point","title":"இருவர் ஒன்று குறைவு, மூன்றாமவருக்கு இரண்டு கூடுதல்","body":""}]},{"say":"முதல் இருவரின் மிட்டாய் தீரும் வரை இதைத் திரும்பச் செய்வோம். இறுதியில் எல்லா மிட்டாயும் மூன்றாமவரிடம் இருக்கும். இதுவே பச்சோந்திகள் சிக்கல்.","board":[{"kind":"point","title":"a சுழியம் ஆனால் நிறுத்து","body":""}]}],"example":[{"say":"A, B, C என்பது 2, 2, 3 என்று எடுப்போம். முதல் சுழற்சியில் 1, 1, 5 ஆகும். இரண்டாவதில் 0, 0, 7 ஆகும். இப்போது a சுழியம், நிறுத்துகிறோம். c சமம் 2 கூட்டல் 2 கூட்டல் 3, அதாவது 7 என்பதைச் சரிபார்க்கலாம்.","board":[{"kind":"example","title":"2,2,3 → 1,1,5 → 0,0,7","body":"c = 2+2+3 = 7"}]}],"checkQuestion":{"question":"பச்சோந்திகள் சிக்கலில் ஒவ்வொரு சுழற்சியிலும் a, b, c மதிப்புகள் எப்படி மாறும்? எப்போது நிறுத்துவோம்?","idealAnswer":"ஒவ்வொரு சுழற்சியிலும் a மற்றும் b ஒவ்வொன்றும் ஒன்று குறையும், c இரண்டு அதிகரிக்கும். a சுழியம் ஆனவுடன் நிறுத்துவோம். அப்போது a = b = 0 மற்றும் c = A+B+C.","keywords":["a-1","b-1","c+2","a > 0","a = b = 0","ஒன்று குறையும்","இரண்டு அதிகரிக்கும்"]}},{"page":8,"steps":[{"say":"சென்ற பக்கத்தில் குரோமிலேண்டு பச்சோந்தி சிக்கலை செயற்கூறு (function) மூலம் தீர்த்தோம். இப்போது இந்தப் பாடம் முழுவதையும் சுருக்கமாக நினைவுபடுத்திக் கொள்வோம்.","board":[{"kind":"heading","title":"பாடச் சுருக்கம்: செயற்கூறு","body":""}]},{"say":"நெறிமுறைகள் நிரலாக்க மொழியின் கூற்றுகளைப் பயன்படுத்தி செயல்படுத்தப்படுகின்றன. ஒரு குறிப்பிட்ட செயலை மீண்டும் மீண்டும் செய்யப் பயன்படும் சிறிய நிரல் பகுதி துணை நிரல் (subroutine) எனப்படும். நிரலாக்க மொழிகளில் இதையே செயற்கூறு என்கிறோம்.","board":[{"kind":"keyterm","title":"துணை நிரல் (Subroutine)","body":"ஒரு செயலை மீண்டும் மீண்டும் செய்யப் பயன்படும் சிறிய நிரல் பகுதி"},{"kind":"keyterm","title":"செயற்கூறு (Function)","body":"பெரிய நிரலில் வரையறுக்கப்படும் குறிமுறை அலகு; பல உள்ளீடுகளுக்கு நிலையான வெளியீடு தரும்"}]},{"say":"வரையறைகள் தனித்தன்மையான தொடரியல் தொகுதிகளைக் கொண்டவை. அவை மதிப்பைப் பெயருடன் பிணைக்கின்றன. வரையறைகள் கோவைகள் அல்ல என்பதை நினைவில் வையுங்கள்.","board":[{"kind":"point","title":"வரையறை மதிப்பைப் பெயருடன் பிணைக்கும்; அது கோவை அல்ல","body":""}]},{"say":"அளபுருக்கள் (parameters) என்பவை செயற்கூறு வரையறையில் உள்ள மாறிகள். செயலுருபுகள் (arguments) என்பவை செயற்கூறுக்கு அனுப்பப்படும் மதிப்புகள். இது தேர்வில் அடிக்கடி கேட்கப்படும்.","board":[{"kind":"keyterm","title":"அளபுரு (Parameter)","body":"செயற்கூறு வரையறையில் உள்ள மாறி"},{"kind":"keyterm","title":"செயலுருபு (Argument)","body":"செயற்கூறுக்கு அனுப்பப்படும் மதிப்பு"}]},{"say":"தரவு வகைக்குக் குறிப்பு எழுதும்போது, செயற்கூறு வரையறையில் அடைப்புக்குறிகள் கட்டாயம். தன்னைத் தானே அழைக்கும் செயற்கூறு தற்சுழற்சி செயற்கூறு (recursive function); அதற்கு let rec பயன்படுத்துகிறோம்.","board":[{"kind":"warning","title":"தரவு வகை குறிப்புக்கு ( ) அடைப்புக்குறி கட்டாயம்","body":""}]},{"say":"இடைமுகம் (interface) என்பது ஒரு பொருள் செய்யக்கூடிய செயல்களை வரையறுக்கிறது; ஆனால் அவற்றை உண்மையில் செய்வதில்லை. செயல்படுத்துதல் (implementation) இடைமுகத்தில் வரையறுத்த கட்டளைகளை நிறைவேற்றுகிறது. காரின் accelerator இடைமுகம்; இயந்திரம் செயல்படுத்துதல்.","board":[{"kind":"point","title":"இடைமுகம் = என்ன செய்யலாம்; செயல்படுத்துதல் = எப்படிச் செய்கிறது","body":""}]},{"say":"ஒரே செயலுருபுகளுக்கு எப்போதும் ஒரே விடை தந்து, பக்க விளைவு இல்லாத செயற்கூறு pure செயற்கூறு. impure செயற்கூறு பக்க விளைவுகளை ஏற்படுத்தும்; வெவ்வேறு விடைகள் தரலாம். random என்பது impure. இது ஐந்து மதிப்பெண் கேள்விக்கு முக்கியம்.","board":[{"kind":"keyterm","title":"Pure செயற்கூறு","body":"அதே செயலுருபுகள் என்றால் அதே விடை; பக்க விளைவு இல்லை"},{"kind":"keyterm","title":"Impure செயற்கூறு","body":"பக்க விளைவு உண்டு; விடை மாறலாம். எ.கா. random()"}]}],"explainAgain":[{"say":"செயற்கூறு என்பது வீட்டில் உள்ள மிக்சி போன்றது. ஒவ்வொரு முறையும் பழங்களைப் போடுகிறோம், அது ஜூஸ் தருகிறது. அதே வேலையை நாமே திரும்பத் திரும்ப செய்ய வேண்டியதில்லை.","board":[]},{"say":"மிக்சியின் சுவிட்ச் இடைமுகம். உள்ளே மோட்டார் சுழல்வது செயல்படுத்துதல். pure செயற்கூறு என்பது வாய்ப்பாடு போன்றது; ஐந்து இரண்டு எப்போதும் பத்து. impure என்பது பகடை உருட்டுவது போல; ஒவ்வொரு முறையும் வேறு எண் வரலாம்.","board":[]}],"example":[{"say":"ஓர் எடுத்துக்காட்டு பார்ப்போம். square செயற்கூறு x பெருக்கல் x தருகிறது. square 5 என்றால் எப்போதும் 25. எனவே இது pure. inc செயற்கூறு வெளி மாறி y-ஐ மாற்றுகிறது. எனவே இது impure.","board":[{"kind":"code","title":"Pure","body":"let square x:=\n return: x * x"},{"kind":"code","title":"Impure (side effect)","body":"y: = 0\nlet inc (x: int): int: =\n y: = y + x\nreturn (y)"}]},{"say":"inc 1 முதல் முறை 1 தரும். இரண்டாம் முறை y ஏற்கனவே 1 ஆக இருப்பதால் 2 தரும். அதே செயலுருபுக்கு வேறு விடை; இதுவே பக்க விளைவு.","board":[]}],"checkQuestion":{"question":"pure செயற்கூறுக்கும் impure செயற்கூறுக்கும் உள்ள முக்கிய வேறுபாடு என்ன?","idealAnswer":"pure செயற்கூறு அதே செயலுருபுகளுக்கு எப்போதும் அதே விடையைத் தரும், பக்க விளைவுகள் இல்லை. impure செயற்கூறு பக்க விளைவுகளை ஏற்படுத்தும், அதே செயலுருபுகளுக்கு வெவ்வேறு விடை தரலாம். எ.கா. random().","keywords":["pure","impure","பக்க விளைவு","side effect","அதே விடை"]}}],"concepts":["துணை நிரல் மற்றும் செயற்கூறு","செயற்கூறு வரையறை","அளபுருக்கள் மற்றும் செயலுருபுகள்","தரவு வகை குறிப்பு","தற்சுழற்சி செயற்கூறு","இடைமுகம் மற்றும் செயல்படுத்துதல்","Pure செயற்கூறு","Impure செயற்கூறு மற்றும் பக்க விளைவு"],"questions":[{"id":"q1","type":"mcq","concept":"துணை நிரல் மற்றும் செயற்கூறு","question":"ஒரு குறிப்பிட்ட செயலை மீண்டும் மீண்டும் செய்யப் பயன்படும் நிரலின் சிறிய பகுதி எது?","code":"","options":["துணை நிரல் (Subroutine)","கோப்பு","தொகுதி","Pseudo குறிமுறை"],"answer":"துணை நிரல் (Subroutine)","keywords":[],"explanation":"நிரலாக்க மொழிகளில் துணை நிரல்கள் செயற்கூறுகள் என அழைக்கப்படுகின்றன."},{"id":"q2","type":"short","concept":"துணை நிரல் மற்றும் செயற்கூறு","question":"செயற்கூறு (function) என்றால் என்ன?","code":"","options":[],"answer":"செயற்கூறு என்பது ஒரு பெரிய நிரலில் வரையறுக்கப்படும் குறிமுறை அலகு; பல உள்ளீடுகளின் மீது செயல்பட்டு நிலையான வெளியீட்டைத் தரும்.","keywords":["குறிமுறை அலகு","பெரிய நிரல்","உள்ளீடு","வெளியீடு"],"explanation":"நூலில் செயற்கூறு குறிமுறையின் அலகு என வரையறுக்கப்பட்டுள்ளது."},{"id":"q3","type":"short","concept":"செயற்கூறு வரையறை","question":"X:=(78) மூலம் அறிவது என்ன?","code":"","options":[],"answer":"இது ஒரு வரையறை; 78 என்ற மதிப்பு X என்ற பெயருடன் பிணைக்கப்படுகிறது. (78) கோவை அல்ல.","keywords":["வரையறை","மதிப்பு","பெயருடன் பிணைப்பு"],"explanation":"வரையறைகள் மதிப்புகளைப் பெயருடன் பிணைக்கின்றன; அவை கோவைகள் அல்ல."},{"id":"q4","type":"mcq","concept":"அளபுருக்கள் மற்றும் செயலுருபுகள்","question":"செயற்கூறு வரையறைக்கு அனுப்பப்படும் மதிப்புகள் எவ்வாறு அழைக்கப்படும்?","code":"","options":["செயலுருபுகள் (arguments)","அளபுருக்கள் (parameters)","துணை நிரல்கள்","இடைமுகம்"],"answer":"செயலுருபுகள் (arguments)","keywords":[],"explanation":"வரையறையில் உள்ள மாறிகள் அளபுருக்கள்; அனுப்பப்படும் மதிப்புகள் செயலுருபுகள்."},{"id":"q5","type":"short","concept":"அளபுருக்கள் மற்றும் செயலுருபுகள்","question":"அளபுருக்கள் (parameters), செயலுருபுகள் (arguments) வேறுபாடு என்ன?","code":"","options":[],"answer":"அளபுருக்கள் செயற்கூறு வரையறையில் உள்ள மாறிகள்; செயலுருபுகள் அழைக்கும்போது அவற்றுக்கு அனுப்பப்படும் மதிப்புகள்.","keywords":["வரையறையில் மாறிகள்","அனுப்பப்படும் மதிப்புகள்"],"explanation":"இது நூலின் நேரடி வரையறை."},{"id":"q6","type":"mcq","concept":"தரவு வகை குறிப்பு","question":"அளபுருவுக்குத் தரவு வகை குறிப்பு (type annotation) எழுதும்போது எது கட்டாயம்?","code":"","options":["( ) அடைப்புக்குறி","{ } அடைப்புக்குறி","[ ] அடைப்புக்குறி","< > குறி"],"answer":"( ) அடைப்புக்குறி","keywords":[],"explanation":"எ.கா. (a: int) என எழுத வேண்டும்."},{"id":"q7","type":"short","concept":"தரவு வகை குறிப்பு","question":"தரவு வகையை வெளிப்படையாக எழுதுவதால் என்ன பயன்?","code":"","options":[],"answer":"பொருளற்ற தரவு வகை பிழைச் செய்தி வரும்போது பிழையைத் திருத்த உதவும்.","keywords":["பிழைச் செய்தி","திருத்தம்"],"explanation":"நிரல்பெயர்ப்பி வகையை அனுமானிக்கும், ஆனாலும் குறிப்பு பிழை திருத்த உதவும்."},{"id":"q8","type":"mcq","concept":"தற்சுழற்சி செயற்கூறு","question":"தன்னைத் தானே அழைக்கும் செயற்கூறை வரையறுக்க எந்தச் சிறப்புச் சொல் பயன்படுகிறது?","code":"","options":["let rec","let only","define","return"],"answer":"let rec","keywords":[],"explanation":"தற்சுழற்சிக்கு let-க்குப் பதிலாக let rec பயன்படுத்த வேண்டும்."},{"id":"q9","type":"predict_output","concept":"தற்சுழற்சி செயற்கூறு","question":"gcd 13 27 இன் வெளியீடு என்ன?","code":"let rec gcd a b :=\n if b <> 0 then gcd b (a mod b)\n else\n return a","options":[],"answer":"1","keywords":[],"explanation":"13 மற்றும் 27 இன் மீப்பெரு வகுஎண் 1; நூலிலும் வெளியீடு 1."},{"id":"q10","type":"predict_output","concept":"தற்சுழற்சி செயற்கூறு","question":"gcd 20536 7826 இன் வெளியீடு என்ன?","code":"let rec gcd a b :=\n if b <> 0 then gcd b (a mod b)\n else\n return a","options":[],"answer":"2","keywords":[],"explanation":"நூலில் கொடுக்கப்பட்ட வெளியீடு 2."},{"id":"q11","type":"mcq","concept":"இடைமுகம் மற்றும் செயல்படுத்துதல்","question":"இடைமுகத்தில் வரையறுக்கப்பட்ட கட்டளைகளை நிறைவேற்றுவது எது?","code":"","options":["செயல்படுத்துதல் (implementation)","இயக்க அமைப்பு","நிரல் பெயர்ப்பி","தொகுப்பான்"],"answer":"செயல்படுத்துதல் (implementation)","keywords":[],"explanation":"இடைமுகம் செயலை வரையறுக்கும்; செயல்படுத்துதல் அதைச் செய்யும்."},{"id":"q12","type":"short","concept":"இடைமுகம் மற்றும் செயல்படுத்துதல்","question":"இடைமுகத்தையும் செயல்படுத்துதலையும் எடுத்துக்காட்டுடன் வேறுபடுத்துக.","code":"","options":[],"answer":"இடைமுகம் பொருள் செய்யக்கூடிய செயலை வரையறுக்கும், செய்யாது; செயல்படுத்துதல் அதை நிறைவேற்றும். காரின் accelerator இடைமுகம், இயந்திரம் செயல்படுத்துதல்.","keywords":["வரையறுக்கும்","நிறைவேற்றும்","accelerator","இயந்திரம்"],"explanation":"ஓட்டுநர் உள் செயல்பாடு அறிய வேண்டியதில்லை."},{"id":"q13","type":"mcq","concept":"Pure செயற்கூறு","question":"பின்வருவனவற்றில் pure செயற்கூறு எது?","code":"","options":["square x = x * x","random()","date()","வெளி மாறி y ஐ மாற்றும் inc"],"answer":"square x = x * x","keywords":[],"explanation":"ஒரே உள்ளீட்டுக்கு எப்போதும் ஒரே வெளியீடு தரும்."},{"id":"q14","type":"short","concept":"Pure செயற்கூறு","question":"strlen ஏன் pure செயற்கூறு எனப்படுகிறது?","code":"","options":[],"answer":"ஒரே மாறியை அளபுருவாக எடுத்து நீளத்தைக் கணக்கிடும்; மதிப்புகளை மாற்றாது, பக்க விளைவு இல்லை.","keywords":["ஒரே அளபுரு","மாற்றாது","பக்க விளைவு இல்லை"],"explanation":"அதனால் தேவையற்ற அழைப்புகளை நீக்க முடியும்."},{"id":"q15","type":"short","concept":"Impure செயற்கூறு மற்றும் பக்க விளைவு","question":"impure செயற்கூறின் பக்க விளைவை ஒரு எடுத்துக்காட்டுடன் விளக்குக.","code":"y := 0\nlet inc (x: int): int :=\n y := y + x\n return (y)","options":[],"answer":"inc செயற்கூறு வெளிப்புற மாறி y இன் மதிப்பை மாற்றுவதால், ஒவ்வொரு அழைப்பிலும் விடை மாறும்; இது பக்க விளைவு.","keywords":["வெளிப்புற மாறி","y மாறுகிறது","விடை மாறும்"],"explanation":"செயற்கூறுக்கு வெளியே மாறியை மாற்றுவது பக்க விளைவு."},{"id":"q16","type":"mcq","concept":"Impure செயற்கூறு மற்றும் பக்க விளைவு","question":"random() எந்த வகை செயற்கூறு?","code":"","options":["Impure செயற்கூறு","Pure செயற்கூறு","Dynamic செயற்கூறு","Partial செயற்கூறு"],"answer":"Impure செயற்கூறு","keywords":[],"explanation":"ஒரே அழைப்புக்கு வெவ்வேறு வெளியீடுகள் தருவதால் impure."}],"reteach":{"தரவு வகை குறிப்பு":[{"steps":[{"say":"வணக்கம்! நாம் இப்போது தரவு வகை குறிப்பு (type annotation) பற்றி புதிதாகப் பார்ப்போம். இது எளிதான பகுதிதான், கவலை வேண்டாம்.","board":[{"kind":"heading","title":"தரவு வகை குறிப்பு (Type Annotation)","body":""}]},{"say":"பள்ளியில் ஒவ்வொரு பெட்டியிலும் லேபிள் ஒட்டுவோம். இது பென்சில் பெட்டி, இது புத்தகப் பெட்டி என்று. அதுபோல, செயற்கூறில் உள்ள ஒவ்வொரு அளபுருவுக்கும் அது என்ன வகை மதிப்பு என்று லேபிள் ஒட்டுவதே தரவு வகை குறிப்பு.","board":[{"kind":"keyterm","title":"தரவு வகை குறிப்பு","body":"அளபுருவின் தரவு வகையை வெளிப்படையாக எழுதுவது"}]},{"say":"புத்தகத்தில் pow என்ற செயற்கூறு உள்ளது. அதில் a மற்றும் b இரண்டும் int வகை. செயற்கூறு திருப்பித் தரும் மதிப்பும் int வகை. இதை எழுதும் முறையைப் பாருங்கள்.","board":[{"kind":"code","title":"வகை குறிப்புடன் pow","body":"let rec pow (a: int) (b: int) : int :=\n    if b=0 then 1\n    else a * pow b (a-1)"}]},{"say":"இங்கே a colon int என்பது a ஒரு int என்று சொல்கிறது. இதை அடைப்புக்குறிக்குள் எழுத வேண்டும். இது தேர்வுக்கு மிக முக்கியம்: வகை குறிப்பு எழுதும்போது சாதாரண அடைப்புக்குறிகள் கட்டாயம்.","board":[{"kind":"warning","title":"வகை குறிப்புக்கு ( ) கட்டாயம்","body":""}]},{"say":"வகை குறிப்பு எழுதாமலும் விடலாம். ஏனெனில் நிரல்பெயர்ப்பி (compiler) வகையை தானே அனுமானித்துக் கொள்ளும். ஆனால் வெளிப்படையாக எழுதினால், பிழைச் செய்தியைத் திருத்த உதவும்.","board":[{"kind":"point","title":"குறிப்பு விடலாம்; எழுதினால் பிழை திருத்த உதவும்","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"தரவு வகை குறிப்பு","question":"செயற்கூறு வரையறையில் தரவு வகை குறிப்பு எழுதும்போது எந்த அடைப்புக்குறி கட்டாயம்?","code":"","options":["( )","{ }","[ ]","< >"],"answer":"( )","keywords":[],"explanation":"வகை குறிப்புகளை சாதாரண அடைப்புக்குறிக்குள் எழுத வேண்டும்."},{"id":"p2","type":"short","concept":"தரவு வகை குறிப்பு","question":"வகை குறிப்பை வெளிப்படையாக எழுதுவதன் ஒரு பயன் என்ன?","code":"","options":[],"answer":"பொருளற்ற தரவு வகை பிழைச் செய்தி வரும்போது, அதைத் திருத்த வெளிப்படையான வகை குறிப்பு உதவுகிறது.","keywords":["பிழைச் செய்தி","திருத்த","தரவு வகை"],"explanation":"வகையை எழுதினால் பிழையின் காரணத்தை எளிதில் கண்டறியலாம்."}]},{"steps":[{"say":"மிக எளிமையாக, படிப்படியாகப் பார்ப்போம். தரவு வகை குறிப்பு (type annotation) என்றால் மதிப்பின் வகையை எழுதிக் காட்டுவது.","board":[{"kind":"heading","title":"தரவு வகை குறிப்பு - எளிய விளக்கம்","body":""}]},{"say":"ஒரு பேருந்து டிக்கெட்டில் பயணியின் வயது என்று எழுதியிருக்கும். அங்கே எண் தான் எழுத வேண்டும், பெயர் எழுதக்கூடாது. அதுபோல அளபுருவுக்கு என்ன வகை மதிப்பு வரும் என்று சொல்வதே வகை குறிப்பு.","board":[{"kind":"point","title":"அளபுரு எந்த வகை மதிப்பு ஏற்கும் என்று சொல்வது","body":""}]},{"say":"முதல் படி: அடைப்புக்குறி திறக்கவும். இரண்டாம் படி: அளபுருவின் பெயர் எழுதவும். மூன்றாம் படி: colon போடவும். நான்காம் படி: வகை, எடுத்துக்காட்டாக int, எழுதவும். ஐந்தாம் படி: அடைப்புக்குறி மூடவும்.","board":[{"kind":"example","title":"(a: int)","body":"பெயர் a, வகை int"}]},{"say":"கடைசியாக, அளபுருக்களுக்குப் பிறகு colon போட்டு திருப்பும் மதிப்பின் வகையையும் எழுதலாம்.","board":[{"kind":"code","title":"திரும்பும் வகையுடன்","body":"let rec pow (a: int) (b: int) : int :="}]},{"say":"பொதுவான தவறுகள்: அடைப்புக்குறியை மறப்பது, அல்லது சதுர அடைப்புக்குறி பயன்படுத்துவது. தேர்வில் இது அடிக்கடி கேட்கப்படும்.","board":[{"kind":"warning","title":"அடைப்புக்குறி மறக்காதீர்; ( ) மட்டுமே","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"தரவு வகை குறிப்பு","question":"(a: int) என்பதில் int எதைக் குறிக்கிறது?","code":"","options":["a இன் தரவு வகை","செயற்கூறின் பெயர்","a இன் மதிப்பு","நிரலின் பெயர்"],"answer":"a இன் தரவு வகை","keywords":[],"explanation":"colon க்குப் பிறகு உள்ளது அளபுருவின் தரவு வகை."},{"id":"p2","type":"short","concept":"தரவு வகை குறிப்பு","question":"நிரல்பெயர்ப்பி வகை குறிப்பு இல்லாமலும் வகையை எப்படி அறிகிறது?","code":"","options":[],"answer":"நிரல்பெயர்ப்பி தரவு வகையை அனுமானித்து (infer) அறிந்து கொள்கிறது.","keywords":["அனுமானி","நிரல்பெயர்ப்பி"],"explanation":"வகை குறிப்பை விட்டுவிடலாம் ஏனெனில் நிரல்பெயர்ப்பி அதை அனுமானிக்கும்."}]},{"steps":[{"say":"மிக அடிப்படையிலிருந்து தொடங்குவோம். உங்களுக்குத் தெரியும், எண்கள் ஒரு வகை, எழுத்துகள் வேறு வகை. இதுவே தரவு வகை.","board":[{"kind":"heading","title":"அடிப்படை: தரவு வகை","body":""}]},{"say":"int என்றால் முழு எண். 5 அல்லது 20 போன்றவை int வகை. செயற்கூறில் ஒரு மாறிக்கு எந்த வகை என்று சொல்லி எழுதுவதே தரவு வகை குறிப்பு (type annotation).","board":[{"kind":"keyterm","title":"int","body":"முழு எண் வகை"}]},{"say":"ஒரு சிறிய எடுத்துக்காட்டு. x என்ற அளபுரு int வகை என்று இப்படி எழுதுவோம்.","board":[{"kind":"code","title":"எளிய எடுத்துக்காட்டு","body":"let square (x: int) : int :=\n return: x * x"}]},{"say":"நினைவில் கொள்ளுங்கள்: வகை குறிப்பு எழுதினால் அடைப்புக்குறி ( ) கட்டாயம். இதுவே தேர்வுக்கான முக்கியப் புள்ளி.","board":[{"kind":"point","title":"வகை குறிப்பு = ( ) கட்டாயம்","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"தரவு வகை குறிப்பு","question":"(x: int) இல் அடைப்புக்குறி ஏன் எழுதப்படுகிறது?","code":"","options":["வகை குறிப்புக்கு அது கட்டாயம்","அது விருப்பத்திற்குரியது","அது செயற்கூறின் பெயருக்கு","அது கருத்துரைக்கு"],"answer":"வகை குறிப்புக்கு அது கட்டாயம்","keywords":[],"explanation":"தரவு வகை குறிப்பு எழுதும்போது அடைப்புக்குறி அவசியம்."},{"id":"p2","type":"short","concept":"தரவு வகை குறிப்பு","question":"let square (x: int) : int இல் x இன் தரவு வகை என்ன?","code":"","options":[],"answer":"x இன் தரவு வகை int ஆகும்.","keywords":["int","முழு எண்"],"explanation":"x க்குப் பிறகு colon உடன் int எழுதப்பட்டுள்ளது."}]}],"துணை நிரல் மற்றும் செயற்கூறு":[{"steps":[{"say":"வணக்கம். நான் குரு. இந்தப் பகுதியை ஒரு புதிய வழியில் பார்க்கலாம். கவலை வேண்டாம், நீங்கள் நிச்சயம் புரிந்துகொள்வீர்கள்.","board":[{"kind":"heading","title":"துணை நிரல் மற்றும் செயற்கூறு","body":""}]},{"say":"பள்ளியில் ஒரு மணி அடிக்கும் வேலையை நினைத்துப் பாருங்கள். ஒவ்வொரு பாடவேளை முடிவிலும் ஒரே வேலை திரும்பத் திரும்ப நடக்கிறது. அந்த வேலைக்கு ஒரு பெயர் வைத்து, தேவைப்படும்போது அழைத்தால் போதும். இதுவே துணை நிரல்.","board":[{"kind":"keyterm","title":"துணை நிரல் (Subroutine)","body":"ஒரு குறிப்பிட்ட செயலை மீண்டும் மீண்டும் செய்யப் பயன்படும் சிறிய நிரல் தொகுதி"}]},{"say":"நிரலாக்க மொழிகளில் இந்தத் துணை நிரல்களுக்கு செயற்கூறு என்று பெயர். ஆங்கிலத்தில் ஃபங்ஷன் என்பார்கள். தேர்வில் இந்த இரண்டும் ஒன்றே என்பதை நினைவில் கொள்ளுங்கள்.","board":[{"kind":"keyterm","title":"செயற்கூறு (Function)","body":"ஒரு பெரிய நிரலில் வரையறுக்கப்படும் குறிமுறை அலகு"}]},{"say":"செயற்கூறு பல வகை உள்ளீடுகளான மாறிகள், கோவைகள் ஆகியவற்றைப் பெற்று, நிலையான வெளியீட்டைத் தருகிறது. ஒரு எடுத்துக்காட்டாக, ஒரு எண்ணின் வர்க்கத்தைக் காணும் செயற்கூறைப் பாருங்கள்.","board":[{"kind":"code","title":"square செயற்கூறு","body":"let square x:=\n return: x * x"}]},{"say":"இங்கே square என்பது செயற்கூறின் பெயர். x என்பது அளபுரு. நாம் அனுப்பும் மதிப்பு செயலுருபு. இது தேர்வுக்கு முக்கியம்.","board":[{"kind":"warning","title":"அளபுரு என்பது வரையறையில் உள்ள மாறி; செயலுருபு என்பது அனுப்பும் மதிப்பு","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"துணை நிரல் மற்றும் செயற்கூறு","question":"ஒரு குறிப்பிட்ட செயலை மீண்டும் மீண்டும் செய்யப் பயன்படும் சிறிய நிரல் தொகுதி எது?","code":"","options":["துணை நிரல்","கோப்பு","இயக்க அமைப்பு","நிரல் பெயர்ப்பி"],"answer":"துணை நிரல்","keywords":[],"explanation":"மீண்டும் மீண்டும் செய்யப்படும் செயலுக்கான சிறிய நிரல் தொகுதி துணை நிரல் எனப்படும்."},{"id":"p2","type":"short","concept":"துணை நிரல் மற்றும் செயற்கூறு","question":"நிரலாக்க மொழியில் துணை நிரல்கள் எவ்வாறு அழைக்கப்படுகின்றன?","code":"","options":[],"answer":"நிரலாக்க மொழிகளில் துணை நிரல்கள் செயற்கூறுகள் (functions) என்று அழைக்கப்படுகின்றன.","keywords":["செயற்கூறு","function"],"explanation":"துணை நிரலும் செயற்கூறும் ஒரே கருத்தைக் குறிக்கின்றன."}]},{"steps":[{"say":"மிக எளிய சொற்களில், படிப்படியாக மீண்டும் பார்க்கலாம். முதலில் ஒரு சமையல் குறிப்பை நினைத்துக்கொள்ளுங்கள்.","board":[{"kind":"heading","title":"எளிய முறையில் செயற்கூறு","body":""}]},{"say":"அம்மா தோசை சுடும் முறையை ஒரு முறை கற்றுக்கொண்டால், தினமும் அதே முறையைப் பயன்படுத்துகிறார். ஒவ்வொரு முறையும் புதிதாகக் கற்கவேண்டாம். அதேபோல் நிரலில் ஒரு வேலையை ஒருமுறை எழுதி, பலமுறை பயன்படுத்தலாம்.","board":[{"kind":"point","title":"ஒருமுறை எழுது, பலமுறை பயன்படுத்து","body":""}]},{"say":"அந்த சிறிய நிரல் தொகுதிக்கு துணை நிரல் என்று பெயர். நிரலாக்க மொழியில் அதையே செயற்கூறு என்கிறோம்.","board":[{"kind":"keyterm","title":"துணை நிரல் = செயற்கூறு","body":"மீண்டும் பயன்படும் சிறிய குறிமுறை"}]},{"say":"செயற்கூறுக்கு உள்ளீடு கொடுத்தால் வெளியீடு கிடைக்கும். தோசை மாவு உள்ளீடு, தோசை வெளியீடு என்று நினைக்கலாம்.","board":[{"kind":"diagram","title":"உள்ளீடு, செயற்கூறு, வெளியீடு","body":"flowchart TD\nA[\"உள்ளீடு\"] --> B[\"செயற்கூறு\"]\nB --> C[\"வெளியீடு\"]"}]},{"say":"பொதுவான தவறுகளைப் பாருங்கள். துணை நிரல் வேறு, செயற்கூறு வேறு என்று நினைக்கக்கூடாது. மேலும் அளபுருவையும் செயலுருபையும் குழப்பிக்கொள்ளக்கூடாது.","board":[{"kind":"warning","title":"அளபுரு = வரையறையில் மாறி; செயலுருபு = அனுப்பும் மதிப்பு","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"துணை நிரல் மற்றும் செயற்கூறு","question":"ஒரு பெரிய நிரல் கட்டமைப்பில் வரையறுக்கப்படும் அலகு எது?","code":"","options":["செயற்கூறு","கோப்புகள்","இயக்க அமைப்பு","தொகுப்பான்"],"answer":"செயற்கூறு","keywords":[],"explanation":"செயற்கூறு என்பது பெரிய நிரலில் வரையறுக்கப்படும் குறிமுறை அலகு."},{"id":"p2","type":"mcq","concept":"துணை நிரல் மற்றும் செயற்கூறு","question":"செயற்கூறு வரையறையில் உள்ள மாறிகள் எவ்வாறு அழைக்கப்படுகின்றன?","code":"","options":["அளபுருக்கள்","செயலுருபுகள்","கோப்புகள்","தொகுதிகள்"],"answer":"அளபுருக்கள்","keywords":[],"explanation":"வரையறையில் உள்ள மாறிகள் அளபுருக்கள்; அனுப்பப்படும் மதிப்புகள் செயலுருபுகள்."}]},{"steps":[{"say":"மிக அடிப்படையிலிருந்து தொடங்கலாம். நீங்கள் ஏற்கனவே அறிந்தது: நிரல் என்பது கூற்றுகளின் தொகுப்பு.","board":[{"kind":"heading","title":"அடிப்படை: கூற்றுகள் முதல் செயற்கூறு வரை","body":""}]},{"say":"சில கூற்றுகளை பலமுறை எழுத வேண்டியிருந்தால் நேரம் வீணாகும். எனவே அந்தக் கூற்றுகளை ஒரு தொகுதியாக்கி, அதற்கு ஒரு பெயர் தருகிறோம்.","board":[{"kind":"point","title":"பல கூற்றுகள் + ஒரு பெயர் = துணை நிரல்","body":""}]},{"say":"இந்தத் துணை நிரலையே நிரலாக்க மொழியில் செயற்கூறு என்கிறோம். ஒரு எளிய எடுத்துக்காட்டு பாருங்கள். இது ஒரு எண்ணை இரண்டால் பெருக்கும்.","board":[{"kind":"code","title":"எளிய செயற்கூறு","body":"let double x:=\n return: x * 2"}]},{"say":"double என்பது பெயர். x என்பது அளபுரு. double 5 என்று அழைத்தால், 5 என்பது செயலுருபு, விடை 10.","board":[{"kind":"example","title":"double 5 என்றால் 10","body":""}]},{"say":"நினைவில் கொள்ளுங்கள்: துணை நிரல்தான் செயற்கூறு. நீங்கள் சிறப்பாகக் கற்றுக்கொள்கிறீர்கள்!","board":[{"kind":"point","title":"துணை நிரல் = செயற்கூறு","body":""}]}],"practice":[{"id":"p1","type":"predict_output","concept":"துணை நிரல் மற்றும் செயற்கூறு","question":"double 5 என்று அழைத்தால் வெளியீடு என்ன?","code":"let double x:=\n return: x * 2","options":[],"answer":"10","keywords":[],"explanation":"x இன் மதிப்பு 5; 5 * 2 = 10."},{"id":"p2","type":"short","concept":"துணை நிரல் மற்றும் செயற்கூறு","question":"துணை நிரல் ஏன் பயன்படுகிறது?","code":"","options":[],"answer":"ஒரு செயலை மீண்டும் மீண்டும் செய்ய, அதே கூற்றுகளை மறுபடி எழுதாமல் பயன்படுத்த துணை நிரல் பயன்படுகிறது.","keywords":["மீண்டும்","செயல்","கூற்றுகள்"],"explanation":"மீண்டும் செய்யப்படும் செயலை ஒருமுறை எழுதி பலமுறை பயன்படுத்த உதவுகிறது."}]}],"Pure செயற்கூறு":[{"steps":[{"say":"வணக்கம்! நாம் இப்போது Pure செயற்கூறு (pure function) பற்றி புதிய முறையில் பார்க்கலாம். கவலை வேண்டாம், இது எளிதுதான்.","board":[{"kind":"heading","title":"Pure செயற்கூறு (Pure Function)","body":""}]},{"say":"பள்ளியில் வாய்ப்பாடு புத்தகம் பார்ப்பது போல நினைத்துக் கொள்ளுங்கள். ஏழு ஐந்து எத்தனை என்று பார்த்தால், இன்று, நாளை, எப்போதும் முப்பத்தைந்துதான். அதே உள்ளீட்டுக்கு எப்போதும் அதே விடை. இதுவே pure செயற்கூறு.","board":[{"kind":"keyterm","title":"Pure செயற்கூறு","body":"ஒரே செயலுருபுகளுக்கு எப்போதும் ஒரே விடை தரும்; பக்க விளைவு இல்லை"}]},{"say":"இப்போது ஒரு எடுத்துக்காட்டு. square என்ற செயற்கூறு x-ஐ தானே பெருக்கி விடையைத் தருகிறது. நான்கைக் கொடுத்தால் எப்போதும் பதினாறு கிடைக்கும். வெளி மாறி எதையும் அது பயன்படுத்தவில்லை.","board":[{"kind":"code","title":"square - pure செயற்கூறு","body":"let square x:=\n return: x * x"}]},{"say":"இன்னொரு எடுத்துக்காட்டு sin(0). இதன் விடை எப்போதும் சுழியம். அதனால் இதுவும் pure செயற்கூறு.","board":[{"kind":"point","title":"sin(0) எப்போதும் 0","body":""}]},{"say":"இதன் ஒரு நன்மை: pure செயற்கூறு என்று தெரிந்தால், நிரல்பெயர்ப்பி (compiler) ஒரே அழைப்பை மீண்டும் மீண்டும் கணக்கிட வேண்டியதில்லை. strlen இதற்கு எடுத்துக்காட்டு. இது தேர்வில் முக்கியம்!","board":[{"kind":"warning","title":"Pure செயற்கூறை மதிப்பீடு செய்யும்போது பக்க விளைவு ஏற்படாது","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"Pure செயற்கூறு","question":"பின்வருவனவற்றுள் எது pure செயற்கூறின் பண்பு?","code":"","options":["ஒரே செயலுருபுகளுக்கு எப்போதும் ஒரே விடை","ஒவ்வொரு முறையும் வேறு விடை","வெளி மாறியை மாற்றும்","random எண்ணைத் தரும்"],"answer":"ஒரே செயலுருபுகளுக்கு எப்போதும் ஒரே விடை","keywords":[],"explanation":"Pure செயற்கூறு ஒரே உள்ளீட்டுக்கு ஒரே வெளியீட்டைத் தரும்."},{"id":"p2","type":"short","concept":"Pure செயற்கூறு","question":"square செயற்கூறு ஏன் pure செயற்கூறு?","code":"let square x:=\n return: x * x","options":[],"answer":"ஒரே உள்ளீட்டுக்கு எப்போதும் ஒரே வெளியீட்டைத் தருகிறது, பக்க விளைவு இல்லை.","keywords":["ஒரே உள்ளீடு","ஒரே வெளியீடு","பக்க விளைவு இல்லை"],"explanation":"விடை x-ஐ மட்டுமே சார்ந்தது."}]},{"steps":[{"say":"மிக எளிய சொற்களில் மீண்டும் பார்க்கலாம். பயப்பட வேண்டாம், படிப்படியாகப் போவோம்.","board":[{"kind":"heading","title":"Pure செயற்கூறு - எளிய விளக்கம்","body":""}]},{"say":"படி ஒன்று: செயற்கூறு என்பது ஒரு இயந்திரம் போன்றது. உள்ளே மதிப்பு போடுகிறோம், வெளியே விடை வருகிறது. இது ஒரு சாறு பிழியும் இயந்திரம் போல.","board":[{"kind":"diagram","title":"உள்ளீடு முதல் வெளியீடு வரை","body":"flowchart TD\nA[\"செயலுருபு\"] --> B[\"செயற்கூறு\"]\nB --> C[\"விடை\"]"}]},{"say":"படி இரண்டு: கணிப்பான் (calculator) போல. இரண்டு கூட மூன்று என்று அழுத்தினால் எப்போதும் ஐந்து வரும். இதுதான் pure செயற்கூறு.","board":[{"kind":"point","title":"அதே உள்ளீடு, அதே விடை","body":""}]},{"say":"படி மூன்று: ஆனால் பகடை உருட்டுவது போல ஒரு செயற்கூறு இருந்தால், ஒவ்வொரு முறையும் வேறு எண் வரும். random() இப்படிப்பட்டது. இது impure செயற்கூறு.","board":[{"kind":"keyterm","title":"Impure செயற்கூறு","body":"random(), date() - ஒவ்வொரு முறையும் வேறு விடை"}]},{"say":"பொதுவான தவறுகள்: முதலாவது, pure என்றால் சிறந்தது, impure என்றால் கெட்டது என்று நினைப்பது. அது தவறு. இரண்டாவது, செயலுருபு மாறினால் விடை மாறக்கூடாது என்று நினைப்பது. அதுவும் தவறு. செயலுருபு அதேயாக இருக்கும்போது விடை அதேயாக இருக்க வேண்டும்.","board":[{"kind":"warning","title":"செயலுருபு மாறினால் விடை மாறலாம்; செயலுருபு அதே என்றால் விடை அதே","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"Pure செயற்கூறு","question":"பின்வருவனவற்றுள் எது impure செயற்கூறு?","code":"","options":["random()","sin(0)","square(4)","strlen(s)"],"answer":"random()","keywords":[],"explanation":"random() ஒவ்வொரு முறையும் வேறு விடை தரும்."},{"id":"p2","type":"short","concept":"Pure செயற்கூறு","question":"pure செயற்கூறு என்றால் என்ன? ஓர் எடுத்துக்காட்டு தருக.","code":"","options":[],"answer":"ஒரே செயலுருபுகளுக்கு எப்போதும் ஒரே விடை தரும் செயற்கூறு; எ.கா. sin(0).","keywords":["ஒரே செயலுருபு","ஒரே விடை","எடுத்துக்காட்டு"],"explanation":"இது பக்க விளைவு இல்லாத செயற்கூறு."}]},{"steps":[{"say":"மிக அடிப்படையிலிருந்து தொடங்குவோம். நீங்கள் ஏற்கெனவே அறிந்தது: செயற்கூறு உள்ளீட்டைப் பெற்று விடை தரும்.","board":[{"kind":"heading","title":"அடிப்படை: Pure செயற்கூறு","body":""}]},{"say":"Pure என்றால் தூய்மையானது. அது உள்ளீட்டை மட்டுமே நம்பி விடை தரும். வேறு எதையும் தொடாது, மாற்றாது.","board":[{"kind":"keyterm","title":"Pure","body":"விடை செயலுருபுகளை மட்டுமே சார்ந்தது"}]},{"say":"மிக எளிய எடுத்துக்காட்டு: square. நான்கு கொடுத்தால் பதினாறு. மூன்று கொடுத்தால் ஒன்பது. எப்போதும் இப்படியே.","board":[{"kind":"code","title":"square","body":"let square x:=\n return: x * x"}]},{"say":"ஒரு செயற்கூறு வெளியே உள்ள மாறி y-ஐ மாற்றினால், அது பக்க விளைவு. அப்போது அது pure அல்ல. நினைவில் வையுங்கள்: pure செயற்கூறில் பக்க விளைவு இல்லை.","board":[{"kind":"code","title":"inc - impure","body":"y: = 0\nlet inc (x: int): int: =\n y: = y + x\nreturn (y)"}]}],"practice":[{"id":"p1","type":"mcq","concept":"Pure செயற்கூறு","question":"inc செயற்கூறு ஏன் pure அல்ல?","code":"y: = 0\nlet inc (x: int): int: =\n y: = y + x\nreturn (y)","options":["வெளி மாறி y-ஐ மாற்றுகிறது","அது x-ஐப் பயன்படுத்துகிறது","அது int தருகிறது","அதற்கு பெயர் உள்ளது"],"answer":"வெளி மாறி y-ஐ மாற்றுகிறது","keywords":[],"explanation":"வெளி மாறியை மாற்றுவது பக்க விளைவு, எனவே impure."},{"id":"p2","type":"short","concept":"Pure செயற்கூறு","question":"strlen ஏன் pure செயற்கூறு?","code":"","options":[],"answer":"அது ஒரு சரத்தின் நீளத்தை மட்டும் கணக்கிடுகிறது, மதிப்புகளை மாற்றுவதில்லை.","keywords":["நீளம்","மாற்றுவதில்லை","பக்க விளைவு இல்லை"],"explanation":"strlen உள்ளீட்டை மட்டுமே படிக்கும், மாற்றாது."}]}],"தற்சுழற்சி செயற்கூறு":[{"steps":[{"say":"வணக்கம்! நாம் தற்சுழற்சி செயற்கூறு (recursive function) பற்றி மீண்டும் புதிய முறையில் பார்க்கலாம். கவலை வேண்டாம், இது எளிது.","board":[{"kind":"heading","title":"தற்சுழற்சி செயற்கூறு (Recursive function)","body":""}]},{"say":"தன்னைத் தானே அழைத்துக் கொள்ளும் செயற்கூறுக்குத் தற்சுழற்சி செயற்கூறு என்று பெயர். இதை எழுத let என்பதற்குப் பதிலாக let rec என்று எழுத வேண்டும்.","board":[{"kind":"keyterm","title":"தற்சுழற்சி செயற்கூறு","body":"தன்னைத் தானே அழைக்கும் செயற்கூறு; let rec பயன்படுத்தப்படும்"}]},{"say":"ஒரு அனலாஜி பார்ப்போம். வகுப்பில் கடைசி பெஞ்சு மாணவர் உங்கள் நோட்டைக் கேட்கிறார். நீங்கள் முன் பெஞ்சுக்குத் தருகிறீர்கள். அவர் அடுத்தவருக்குத் தருகிறார். முதல் பெஞ்சில் ஆசிரியர் இருந்தால் நிறுத்தப்படும். அந்த இடமே நிறுத்தும் நிபந்தனை.","board":[{"kind":"point","title":"ஒவ்வொரு அழைப்பும் சிறிய வேலையைத் தருகிறது","body":""}]},{"say":"இப்போது factorial எடுத்துக்காட்டு. n சுழியம் என்றால் விடை 1. இல்லையெனில் n பெருக்கல் fact of n minus 1. இங்கு fact தன்னையே அழைக்கிறது.","board":[{"kind":"code","title":"Factorial","body":"let rec fact n :=\n    if n = 0 then 1\n    else\n        n * fact(n-1)"}]},{"say":"fact 3 எனில்: 3 பெருக்கல் fact 2. அது 2 பெருக்கல் fact 1. அது 1 பெருக்கல் fact 0. fact 0 என்பது 1. எனவே விடை 6. தேர்வில் நிறுத்தும் நிபந்தனையைக் குறிப்பிட மறக்காதீர்கள்.","board":[{"kind":"example","title":"fact 3 = 3 * 2 * 1 * 1 = 6","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"தற்சுழற்சி செயற்கூறு","question":"தற்சுழற்சி செயற்கூறு என்பது எது?","code":"","options":["தன்னைத் தானே அழைத்துக் கொள்ளும் செயற்கூறு","எந்த அளபுருவும் இல்லாத செயற்கூறு","பக்க விளைவுகள் மட்டும் உள்ள செயற்கூறு","மாறும் வரையறை கொண்ட செயற்கூறு"],"answer":"தன்னைத் தானே அழைத்துக் கொள்ளும் செயற்கூறு","keywords":[],"explanation":"தன்னைத் தானே அழைக்கும் செயற்கூறு வரையறை தற்சுழற்சி செயற்கூறு ஆகும்."},{"id":"p2","type":"short","concept":"தற்சுழற்சி செயற்கூறு","question":"factorial செயற்கூறில் தற்சுழற்சியை நிறுத்தும் கூற்று எது?","code":"let rec fact n :=\n    if n = 0 then 1\n    else\n        n * fact(n-1)","options":[],"answer":"n = 0 எனில் 1 திருப்பி அனுப்பும் கூற்று தற்சுழற்சியை நிறுத்தும்.","keywords":["n = 0","1","நிறுத்தும்"],"explanation":"n சுழியம் ஆனால் செயற்கூறு தன்னை அழைக்காமல் 1 ஐத் தரும்."}]},{"steps":[{"say":"சரி, மிக எளிய சொற்களில் படிப்படியாகப் பார்ப்போம். தற்சுழற்சி என்றால் தன்னையே மீண்டும் அழைத்தல்.","board":[{"kind":"heading","title":"தற்சுழற்சி - எளிய விளக்கம்","body":""}]},{"say":"படி ஒன்று: ஒரு பெரிய வேலையை அதே மாதிரியான சிறிய வேலையாக மாற்றுகிறோம். உதாரணமாக, மாடிப்படி ஏறுவது. பத்தாவது படிக்கு ஏற, ஒன்பதாவது படிக்கு ஏறி, ஒரு படி மேலே போகிறோம்.","board":[{"kind":"point","title":"பெரிய வேலை = சிறிய வேலை + ஒரு படி","body":""}]},{"say":"படி இரண்டு: எப்போது நிறுத்துவது என்று சொல்ல வேண்டும். தரைதளம் வந்தால் நிறுத்துவோம். இதை அடிப்படை நிலை என்று சொல்லலாம்.","board":[{"kind":"keyterm","title":"நிறுத்தும் நிபந்தனை","body":"இது இல்லையென்றால் செயற்கூறு முடிவில்லாமல் ஓடும்"}]},{"say":"படி மூன்று: எடுத்துக்காட்டாக, ஒன்று முதல் n வரை கூட்டுத்தொகை. n சுழியம் எனில் விடை சுழியம். இல்லையெனில் n கூட்டல் sum of n minus 1.","board":[{"kind":"code","title":"Sum","body":"let rec sum n :=\n    if n = 0 then 0\n    else n + sum(n-1)"}]},{"say":"பொதுவான தவறுகள்: ஒன்று, rec என்ற சொல்லை மறப்பது. இரண்டு, நிறுத்தும் நிபந்தனையை எழுதாமல் விடுவது. மூன்று, n minus 1 என்று குறைக்காமல் அதே மதிப்பை அனுப்புவது.","board":[{"kind":"warning","title":"rec மறக்காதே; நிறுத்தும் நிபந்தனை வேண்டும்; மதிப்பு குறைய வேண்டும்","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"தற்சுழற்சி செயற்கூறு","question":"தற்சுழற்சி செயற்கூறை வரையறுக்க எந்தச் சிறப்புச் சொல் பயன்படுத்தப்படுகிறது?","code":"","options":["let rec","let only","return rec","def loop"],"answer":"let rec","keywords":[],"explanation":"தற்சுழற்சி செயற்கூறுக்கு let என்பதற்குப் பதிலாக let rec எழுத வேண்டும்."},{"id":"p2","type":"predict_output","concept":"தற்சுழற்சி செயற்கூறு","question":"sum 3 இன் வெளியீடு என்ன?","code":"let rec sum n :=\n    if n = 0 then 0\n    else n + sum(n-1)","options":[],"answer":"6","keywords":[],"explanation":"3 + 2 + 1 + 0 = 6."}]},{"steps":[{"say":"மிக அடிப்படையிலிருந்து தொடங்கலாம். செயற்கூறு என்பது ஒரு வேலையைச் செய்யும் சிறிய நிரல் தொகுதி. அதை மீண்டும் மீண்டும் அழைக்கலாம்.","board":[{"kind":"point","title":"செயற்கூறு = மீண்டும் பயன்படும் சிறிய நிரல்","body":""}]},{"say":"சில நேரம் ஒரு செயற்கூறு தனக்குள்ளேயே தன்னை அழைக்கும். அதுவே தற்சுழற்சி செயற்கூறு. அப்போது let rec என்று எழுதுவோம்.","board":[{"kind":"keyterm","title":"let rec","body":"தன்னை அழைக்கும் செயற்கூறு வரையறை"}]},{"say":"மிக எளிய எடுத்துக்காட்டு: எண்ணிக்கை குறைத்தல். n சுழியம் எனில் நிறுத்து. இல்லையெனில் count of n minus 1 ஐ அழைக்கவும்.","board":[{"kind":"code","title":"Countdown","body":"let rec count n :=\n    if n = 0 then 0\n    else count(n-1)"}]},{"say":"ஒவ்வொரு முறையும் n ஒன்று குறைகிறது. கடைசியில் n சுழியம் ஆகி நிற்கிறது. நீங்கள் இதைச் சரியாகப் புரிந்து கொள்வீர்கள்!","board":[{"kind":"diagram","title":"அழைப்பு வரிசை","body":"flowchart TD\nA[\"count 2\"] --> B[\"count 1\"]\nB --> C[\"count 0\"]\nC --> D[\"நிற்கும்\"]"}]}],"practice":[{"id":"p1","type":"mcq","concept":"தற்சுழற்சி செயற்கூறு","question":"பின்வருவனவற்றுள் தற்சுழற்சி செயற்கூறு எது?","code":"","options":["let rec sum num: if num != 0 then return num + sum(num-1) else return num","let sum x y: return x + y","let disp: print 'welcome'","let square x: return x * x"],"answer":"let rec sum num: if num != 0 then return num + sum(num-1) else return num","keywords":[],"explanation":"இது let rec பயன்படுத்தி sum ஐத் தானே அழைக்கிறது."},{"id":"p2","type":"short","concept":"தற்சுழற்சி செயற்கூறு","question":"gcd செயற்கூறில் தன்னைத் தானே அழைக்கும் கூற்று எது?","code":"let rec gcd a b :=\n    if b <> 0 then gcd b (a mod b)\n    else return a","options":[],"answer":"gcd b (a mod b) என்ற கூற்று செயற்கூறைத் தானே அழைக்கிறது.","keywords":["gcd b (a mod b)","அழைக்கிறது"],"explanation":"b சுழியம் அல்லாதபோது gcd தன்னை அளபுருக்கள் b மற்றும் a mod b உடன் அழைக்கும்."}]}],"செயற்கூறு வரையறை":[{"steps":[{"say":"வணக்கம்! நான் குரு. இன்று செயற்கூறு வரையறையை (function definition) ஒரு புதிய வழியில் பார்க்கலாம். பயப்பட வேண்டாம், இது எளிது.","board":[{"kind":"heading","title":"செயற்கூறு வரையறை (Function Definition)","body":""}]},{"say":"பள்ளியில் ஒரு சமையல் குறிப்பு அட்டை போல நினைத்துக் கொள்ளுங்கள். அட்டையில் பெயர், தேவையான பொருட்கள், செய்முறை இருக்கும். அதே போல செயற்கூறு வரையறையிலும் பெயர், அளபுருக்கள், உடல் பகுதி இருக்கும். ஒரு முறை எழுதினால் பலமுறை பயன்படுத்தலாம்.","board":[{"kind":"point","title":"பெயர் + அளபுருக்கள் + கணக்கீடு","body":""}]},{"say":"புத்தகத்தில் தொடரியல் இப்படி உள்ளது. let என்ற சிறப்புச் சொல்லுடன் தொடங்கும். பிறகு செயற்கூறின் பெயர். பிறகு அளபுருக்கள். பிறகு இரண்டு புள்ளி சமம் குறிக்குப் பின் கணக்கீடு வாய்ப்பாடு. தன்னைத் தானே அழைத்தால் let rec என்று எழுத வேண்டும்.","board":[{"kind":"code","title":"தொடரியல்","body":"let rec fn a1 a2 ... an := k"},{"kind":"keyterm","title":"rec","body":"தற்சுழற்சி செயற்கூறுக்கு தேவையான சிறப்புச் சொல்"}]},{"say":"ஒரு எடுத்துக்காட்டு பார்க்கலாம். fact என்பது தொடர் பெருக்கலைக் கணக்கிடும் செயற்கூறு. n சுழியம் எனில் 1 தரும். இல்லையெனில் n பெருக்கல் fact n கழித்தல் 1. இது தன்னையே அழைப்பதால் let rec பயன்படுத்தப்பட்டது.","board":[{"kind":"code","title":"fact செயற்கூறு","body":"(Requires: n>= 0)\nlet rec fact n :=\n    if n = 0 then 1\n    else\n        n * fact(n-1)"}]},{"say":"அளபுருக்கள் என்பவை வரையறையில் உள்ள மாறிகள். செயலுருபுக்கள் என்பவை அழைக்கும் போது அனுப்பும் மதிப்புகள். இது தேர்வில் அடிக்கடி கேட்கப்படும். மேலும், a:=24 என்பது கோவை அல்ல, வரையறை. மதிப்பை பெயருடன் பிணைக்கிறது.","board":[{"kind":"warning","title":"வரையறை கோவை அல்ல; மதிப்பைப் பெயருடன் பிணைக்கும்","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"செயற்கூறு வரையறை","question":"தன்னைத் தானே அழைக்கும் செயற்கூறை வரையறுக்க எந்த சிறப்புச் சொல் பயன்படுத்தப்படுகிறது?","code":"","options":["let rec","let only","define","return"],"answer":"let rec","keywords":[],"explanation":"தற்சுழற்சி செயற்கூறுக்கு let என்பதற்குப் பதிலாக let rec பயன்படுத்தப்படும்."},{"id":"p2","type":"short","concept":"செயற்கூறு வரையறை","question":"let rec fn a1 a2 ... an := k என்ற தொடரியலில் fn மற்றும் a1 முதல் an வரை எவற்றைக் குறிக்கின்றன?","code":"","options":[],"answer":"fn என்பது செயற்கூறின் பெயர்; a1 முதல் an வரை அளபுருக்கள் ஆகும்.","keywords":["செயற்கூறின் பெயர்","அளபுருக்கள்"],"explanation":"fn பெயரையும், a1 முதல் an வரை உள்ள மாறிகள் அளபுருக்களையும் குறிக்கும்."}]},{"steps":[{"say":"பரவாயில்லை, மீண்டும் மிக எளிமையாக படிப்படியாகப் பார்ப்போம். நீங்கள் கண்டிப்பாகப் புரிந்து கொள்வீர்கள்.","board":[{"kind":"heading","title":"எளிய படிகள்","body":""}]},{"say":"படி ஒன்று. செயற்கூறு (function) என்பது ஒரு சிறிய வேலை செய்யும் குறிமுறைத் தொகுதி. தேநீர் இயந்திரம் போல. பொத்தானை அழுத்தினால் தேநீர் கிடைக்கும். உள்ளே என்ன நடக்கிறது என்று தெரிய வேண்டாம்.","board":[{"kind":"point","title":"செயற்கூறு = ஒரு வேலைக்கான குறிமுறைத் தொகுதி","body":""}]},{"say":"படி இரண்டு. வரையறை என்றால் அந்த இயந்திரத்தை உருவாக்கி அதற்கு ஒரு பெயர் வைப்பது. அழைப்பு என்றால் அதைப் பயன்படுத்துவது.","board":[{"kind":"point","title":"வரையறை = உருவாக்குதல்; அழைப்பு = பயன்படுத்துதல்","body":""}]},{"say":"படி மூன்று. எழுதும் முறை. முதலில் let. பிறகு பெயர். பிறகு அளபுருக்கள். பிறகு இரண்டு புள்ளி சமம். பிறகு செய்ய வேண்டிய கணக்கீடு. தன்னையே அழைத்தால் rec சேர்க்க வேண்டும்.","board":[{"kind":"code","title":"எளிய செயற்கூறு","body":"let square x:=\n return: x * x"}]},{"say":"இங்கு square என்பது பெயர். x என்பது அளபுரு. x பெருக்கல் x என்பது கணக்கீடு. square 5 என்று அழைத்தால் 5 என்பது செயலுருபு.","board":[{"kind":"keyterm","title":"செயலுருபு (argument)","body":"அழைக்கும் போது அனுப்பப்படும் மதிப்பு"}]},{"say":"பொதுவான தவறுகள். ஒன்று, அளபுரு மற்றும் செயலுருபை மாற்றிக் கூறுவது. இரண்டு, தற்சுழற்சிக்கு rec எழுத மறப்பது. மூன்று, தரவு வகை குறிப்பு எழுதும் போது அடைப்புக்குறி மறப்பது.","board":[{"kind":"warning","title":"தரவு வகை குறிப்புக்கு ( ) கட்டாயம்","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"செயற்கூறு வரையறை","question":"let square x := return: x * x என்ற வரையறையில் square என்பது என்ன?","code":"","options":["செயற்கூறின் பெயர்","அளபுரு","செயலுருபு","சிறப்புச் சொல்"],"answer":"செயற்கூறின் பெயர்","keywords":[],"explanation":"let க்குப் பின் வரும் முதல் சொல் செயற்கூறின் பெயர்; x அளபுரு."},{"id":"p2","type":"short","concept":"செயற்கூறு வரையறை","question":"செயற்கூறு வரையறையில் தரவு வகை குறிப்பு எழுதும் போது எது கட்டாயம்?","code":"","options":[],"answer":"அடைப்புக்குறிகள் ( ) கட்டாயம்.","keywords":["அடைப்புக்குறி","( )"],"explanation":"type annotations எழுதும் போது அளபுருவைச் சுற்றி ( ) அவசியம்."}]},{"steps":[{"say":"சரி, மிக அடிப்படையிலிருந்து தொடங்குவோம். நீங்கள் ஏற்கனவே அறிந்தது ஒன்று உண்டு. கணிதத்தில் f of x சமம் x பெருக்கல் x என்று எழுதுவீர்கள். அதுதான் செயற்கூறு!","board":[{"kind":"heading","title":"கணித f(x) போன்றதே","body":""}]},{"say":"கணிதத்தில் f என்பது பெயர். x என்பது உள்ளீடு. x பெருக்கல் x என்பது வேலை. நிரலாக்கத்திலும் அதேதான். அதை எழுதுவதே செயற்கூறு வரையறை.","board":[{"kind":"point","title":"பெயர், உள்ளீடு, வேலை","body":""}]},{"say":"இதோ மிக எளிய எடுத்துக்காட்டு. let என்று தொடங்கி, பெயர் square, உள்ளீடு x, பிறகு x பெருக்கல் x.","board":[{"kind":"code","title":"மிக எளிய எடுத்துக்காட்டு","body":"let square x:=\n return: x * x"}]},{"say":"நினைவில் கொள்ளுங்கள். வரையறை என்றால் செயற்கூறை எழுதுவது. let என்ற சிறப்புச் சொல்லுடன் தொடங்கும். தன்னையே அழைத்தால் let rec. தேர்வில் இதை எழுதினால் மதிப்பெண் உறுதி. நீங்கள் செய்துவிடுவீர்கள்!","board":[{"kind":"point","title":"தொடக்கம்: let; தற்சுழற்சி: let rec","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"செயற்கூறு வரையறை","question":"செயற்கூறு வரையறை எந்தச் சிறப்புச் சொல்லுடன் தொடங்குகிறது?","code":"","options":["let","print","loop","end"],"answer":"let","keywords":[],"explanation":"புத்தகத்தில் வரையறை let என்ற சிறப்புச் சொல்லுடன் அறிமுகப்படுத்தப்படுகிறது."},{"id":"p2","type":"short","concept":"செயற்கூறு வரையறை","question":"let rec fact n என்பதில் rec என்பது எதைக் குறிக்கிறது?","code":"","options":[],"answer":"செயற்கூறு தன்னைத் தானே அழைக்கும் தற்சுழற்சி செயற்கூறு என்பதைக் குறிக்கிறது.","keywords":["தற்சுழற்சி","தன்னைத் தானே அழைக்கும்"],"explanation":"rec என்பது recursive என்பதைக் குறிக்கும்; செயற்கூறு தன்னையே அழைக்கும்."}]}],"இடைமுகம் மற்றும் செயல்படுத்துதல்":[{"steps":[{"say":"வணக்கம்! நான் குரு. இடைமுகம் (interface) மற்றும் செயல்படுத்துதல் (implementation) பற்றி புதிய உதாரணத்துடன் மீண்டும் பார்க்கலாம். கவலை வேண்டாம், இது எளிது.","board":[{"kind":"heading","title":"இடைமுகம் vs செயல்படுத்துதல்","body":""}]},{"say":"பள்ளி கேண்டீனை நினைத்துப் பாருங்கள். மெனு பலகையில் இட்லி, தோசை, வடை என்று எழுதியிருக்கும். அந்த மெனுதான் இடைமுகம். என்ன கேட்கலாம் என்பதை மட்டும் சொல்லும். ஆனால் சமைக்காது.","board":[{"kind":"point","title":"மெனு = இடைமுகம்: என்ன செய்ய முடியும் என்று சொல்லும்","body":""}]},{"say":"சமையலறையில் சமையல்காரர் உண்மையில் தோசை சுடுகிறார். அது செயல்படுத்துதல். நீங்கள் எப்படிச் சுடுகிறார் என்று தெரிந்து கொள்ளத் தேவையில்லை.","board":[{"kind":"point","title":"சமையலறை = செயல்படுத்துதல்: உண்மையில் செய்யும்","body":""}]},{"say":"பாடநூலில் உள்ள உதாரணம் மின் விளக்கு. சுவிட்சை அழுத்தினால் விளக்கு எரியும். turn_on மற்றும் turn_off என்பவை இடைமுகம். உள்ளே மின்சாரம் எப்படி வேலை செய்கிறது என்பது செயல்படுத்துதல்.","board":[{"kind":"code","title":"மின் விளக்கு இடைமுகம்","body":"turn_on()\nturn_off()"}]},{"say":"இன்னொரு உதாரணம் கார். ஓட்டுநர் accelerator அழுத்துகிறார். அதுதான் இடைமுகம். இயந்திரம் எரிபொருளைப் பயன்படுத்தி வேகத்தை உயர்த்துவது செயல்படுத்துதல். இடைமுகத்தை செயல்படுத்துதலிலிருந்து பிரித்து வைக்கிறோம். தேர்வில் இந்த வேறுபாடு முக்கியம்.","board":[{"kind":"warning","title":"இடைமுகம் வேலை செய்யாது; வரையறுக்கும் மட்டுமே","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"இடைமுகம் மற்றும் செயல்படுத்துதல்","question":"கேண்டீன் உதாரணத்தில் மெனு பலகை எதைக் குறிக்கிறது?","code":"","options":["இடைமுகம்","செயல்படுத்துதல்","அளபுரு","செயலுருபு"],"answer":"இடைமுகம்","keywords":[],"explanation":"மெனு என்ன கேட்கலாம் என்று மட்டும் சொல்லும்; அதுவே இடைமுகம்."},{"id":"p2","type":"short","concept":"இடைமுகம் மற்றும் செயல்படுத்துதல்","question":"இடைமுகத்தையும் செயல்படுத்துதலையும் ஒரு வரியில் வேறுபடுத்துக.","code":"","options":[],"answer":"இடைமுகம் ஒரு பொருள் செய்யக்கூடிய செயல்களை வரையறுக்கும்; செயல்படுத்துதல் அவற்றை உண்மையில் நிறைவேற்றும்.","keywords":["வரையறுக்கும்","நிறைவேற்றும்","செயல்கள்"],"explanation":"இடைமுகம் வரையறை மட்டுமே; செயல்படுத்துதல் உண்மையான வேலை."}]},{"steps":[{"say":"சரி, மிக எளிய சொற்களில் படிப்படியாகப் பார்க்கலாம். முதலில் ஒரு தொலைக்காட்சி ரிமோட்டை நினைத்துக் கொள்ளுங்கள்.","board":[{"kind":"heading","title":"எளிய விளக்கம்: ரிமோட்","body":""}]},{"say":"படி ஒன்று. ரிமோட்டில் பொத்தான்கள் உள்ளன. ஒலி அதிகம், ஒலி குறைவு, சேனல் மாற்று. இந்தப் பொத்தான்களின் பட்டியலே இடைமுகம் (interface).","board":[{"kind":"keyterm","title":"இடைமுகம்","body":"ஒரு பொருள் செய்யக்கூடிய செயல்களின் பட்டியல்"}]},{"say":"படி இரண்டு. பொத்தானை அழுத்தியதும் தொலைக்காட்சிக்குள் நடக்கும் வேலை செயல்படுத்துதல் (implementation). அதை நாம் பார்ப்பதில்லை.","board":[{"kind":"keyterm","title":"செயல்படுத்துதல்","body":"இடைமுகத்தில் சொன்ன கட்டளைகளை உண்மையில் நிறைவேற்றுவது"}]},{"say":"படி மூன்று. பாடநூல் உதாரணம். speed 70 என்று அழைப்பது இடைமுகம். இயந்திரம் உள்ளே எரிபொருளைச் சேர்த்து வேகம் தருவது செயல்படுத்துதல்.","board":[{"kind":"code","title":"அழைப்பு","body":"speed(70)"}]},{"say":"பொதுவான தவறுகள். ஒன்று, இடைமுகமே வேலை செய்கிறது என்று நினைப்பது. அது தவறு, அது வரையறை மட்டுமே. இரண்டு, இரண்டையும் ஒன்று என்று குழப்புவது. ஓட்டுநருக்கு இயந்திரம் எப்படி வேலை செய்கிறது என்று தெரிய வேண்டியதில்லை.","board":[{"kind":"warning","title":"இடைமுகம் செயலைச் செய்யாது","body":""}]},{"say":"நினைவில் வைக்க: இடைமுகம் என்றால் என்ன செய்யலாம். செயல்படுத்துதல் என்றால் எப்படிச் செய்கிறது. சிறப்பாகச் செய்வீர்கள்!","board":[{"kind":"point","title":"இடைமுகம் = என்ன; செயல்படுத்துதல் = எப்படி","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"இடைமுகம் மற்றும் செயல்படுத்துதல்","question":"தொலைக்காட்சிக்குள் பொத்தானை அழுத்தியதும் நடக்கும் உண்மையான வேலை எது?","code":"","options":["செயல்படுத்துதல்","இடைமுகம்","பொத்தான்களின் பட்டியல்","செயலுருபு"],"answer":"செயல்படுத்துதல்","keywords":[],"explanation":"கட்டளைகளை உண்மையில் நிறைவேற்றுவது செயல்படுத்துதல்."},{"id":"p2","type":"mcq","concept":"இடைமுகம் மற்றும் செயல்படுத்துதல்","question":"காரில் accelerator அழுத்துவது எதற்கு உதாரணம்?","code":"","options":["இடைமுகம்","இயந்திரத்தின் செயல்படுத்துதல்","pure செயற்கூறு","தற்சுழற்சி"],"answer":"இடைமுகம்","keywords":[],"explanation":"accelerator ஓட்டுநருக்கும் இயந்திரத்துக்கும் இடையேயான இடைமுகம்."}]},{"steps":[{"say":"மிக அடிப்படையிலிருந்து தொடங்குவோம். உங்களுக்கு ஏற்கனவே தெரிந்தது: செயற்கூறு (function) ஒரு வேலையைச் செய்யும்.","board":[{"kind":"heading","title":"அடிப்படை: இடைமுகம்","body":""}]},{"say":"வீட்டில் மின் விளக்கு உள்ளது. சுவிட்சைப் போட்டால் எரியும். சுவிட்ச் என்பது இடைமுகம்.","board":[{"kind":"point","title":"சுவிட்ச் = இடைமுகம்","body":""}]},{"say":"வயருக்குள் மின்சாரம் பாய்ந்து விளக்கை ஒளிரச் செய்வது செயல்படுத்துதல். சுவிட்சைப் பயன்படுத்த அது தெரிய வேண்டாம்.","board":[{"kind":"point","title":"உள்ளே நடப்பது = செயல்படுத்துதல்","body":""}]},{"say":"நிரலில் இதை turn_on மற்றும் turn_off என்று எழுதுவோம். இவை விளக்கு செய்யக்கூடிய செயல்களைச் சொல்கின்றன. இதுவே இடைமுகம்.","board":[{"kind":"code","title":"செயற்கூறு பெயர்கள்","body":"turn_on()\nturn_off()"}]},{"say":"சுருக்கம்: இடைமுகம் என்ன செய்யலாம் என்று சொல்லும். செயல்படுத்துதல் அதை உண்மையில் செய்யும். தேர்வில் இதை எழுதினால் மதிப்பெண் கிடைக்கும்.","board":[{"kind":"diagram","title":"தொடர்பு","body":"flowchart TD\nA[\"பயனர்\"] --> B[\"இடைமுகம்\"]\nB --> C[\"செயல்படுத்துதல்\"]"}]}],"practice":[{"id":"p1","type":"mcq","concept":"இடைமுகம் மற்றும் செயல்படுத்துதல்","question":"மின் விளக்கின் சுவிட்ச் எதற்கு உதாரணம்?","code":"","options":["இடைமுகம்","செயல்படுத்துதல்","அளபுரு","pure செயற்கூறு"],"answer":"இடைமுகம்","keywords":[],"explanation":"சுவிட்ச் பயனருக்கும் விளக்குக்கும் இடையேயான இடைமுகம்."},{"id":"p2","type":"short","concept":"இடைமுகம் மற்றும் செயல்படுத்துதல்","question":"மின் விளக்கு உதாரணத்தில் turn_on() என்பது இடைமுகமா அல்லது செயல்படுத்துதலா? ஏன்?","code":"","options":[],"answer":"இது இடைமுகம்; ஏனெனில் விளக்கு செய்யக்கூடிய செயலை மட்டும் குறிக்கிறது, எப்படி எரிகிறது என்பதைக் கூறவில்லை.","keywords":["இடைமுகம்","செயல்","எப்படி"],"explanation":"turn_on() செயலை வரையறுக்கிறது; உள்ளே நடப்பது செயல்படுத்துதல்."}]}],"Impure செயற்கூறு மற்றும் பக்க விளைவு":[{"steps":[{"say":"வணக்கம்! நான் குரு. இன்று impure செயற்கூறு (impure function) மற்றும் பக்க விளைவு (side effect) என்பதை புதிய முறையில் பார்ப்போம். கவலைப்படாதீர்கள், இது எளிதுதான்.","board":[{"kind":"heading","title":"Impure செயற்கூறு மற்றும் பக்க விளைவு","body":""}]},{"say":"பள்ளி கேண்டீனை நினைத்துக் கொள்ளுங்கள். ஒரு தேநீர் கேட்டால் எப்போதும் ஒரே விலை, ஒரே தேநீர். இது pure செயற்கூறு போல. ஆனால் இன்றைய சிறப்பு உணவு என்ன என்று கேட்டால், ஒவ்வொரு நாளும் வேறு பதில் வரும். இது impure செயற்கூறு போல.","board":[{"kind":"point","title":"Pure: அதே உள்ளீடு, அதே விடை","body":""},{"kind":"point","title":"Impure: அதே உள்ளீடு, வேறு விடை வரலாம்","body":""}]},{"say":"Impure செயற்கூறு என்பது, வெளியே உள்ள மாறிகளையோ செயற்கூறுகளையோ சார்ந்திருக்கும் செயற்கூறு. அதனால் ஒவ்வொரு முறை அழைக்கும்போதும் ஒரே விடை கிடைக்கும் என்று உறுதியாகச் சொல்ல முடியாது. உதாரணம் random மற்றும் date.","board":[{"kind":"keyterm","title":"Impure செயற்கூறு","body":"வெளிப்புறத்தைச் சார்ந்து, அதே செயலுருபுக்கு வேறு விடை தரலாம். எ.கா. random(), date()"}]},{"say":"பக்க விளைவு என்பது செயற்கூறு தனக்கு வெளியே உள்ள ஒன்றை மாற்றுவது. உதாரணமாக, வெளியே உள்ள மாறி y என்பதன் மதிப்பை செயற்கூறு மாற்றுகிறது. இதோ புத்தகத்தில் உள்ள எடுத்துக்காட்டு.","board":[{"kind":"code","title":"inc செயற்கூறு","body":"y := 0\nlet inc (x: int): int :=\n y := y + x\n return (y)"}]},{"say":"y பூஜ்யம் என்று தொடங்குகிறது. inc 5 என்று அழைத்தால் y ஐந்து ஆகி, விடை ஐந்து. மீண்டும் inc 5 என்று அழைத்தால் y பத்து ஆகி, விடை பத்து. செயலுருபு (argument) அதேதான், ஆனால் விடை மாறியது. அதனால் இது impure.","board":[{"kind":"example","title":"inc 5 → 5, மீண்டும் inc 5 → 10","body":""}]},{"say":"முக்கியம்! பக்க விளைவு கெட்டது அல்ல. சில நேரம் பயனுள்ளது. இது தேர்வில் மூன்று மதிப்பெண் கேள்வியாக வரும். எடுத்துக்காட்டுடன் எழுத மறக்காதீர்கள்.","board":[{"kind":"warning","title":"பக்க விளைவு எப்போதும் தீமை அல்ல","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"Impure செயற்கூறு மற்றும் பக்க விளைவு","question":"பின்வருவனவற்றுள் எது impure செயற்கூறுக்கு எடுத்துக்காட்டு?","code":"","options":["random()","sin(0)","square x","gcd 13 27"],"answer":"random()","keywords":[],"explanation":"random() ஒரே அழைப்புக்கு வெவ்வேறு விடை தருவதால் impure ஆகும்."},{"id":"p2","type":"predict_output","concept":"Impure செயற்கூறு மற்றும் பக்க விளைவு","question":"y = 0 என்று தொடங்கி inc(3) ஐ இரண்டு முறை அழைத்தால், இரண்டாவது அழைப்பின் விடை என்ன?","code":"y := 0\nlet inc (x: int): int :=\n y := y + x\n return (y)","options":[],"answer":"6","keywords":[],"explanation":"முதல் அழைப்பில் y = 3. இரண்டாவதில் y = 3 + 3 = 6."}]},{"steps":[{"say":"சரி, இப்போது மிக எளிய சொற்களில், படிப்படியாகப் பார்ப்போம். தவறு செய்வது கற்றலின் ஒரு பகுதி.","board":[{"kind":"heading","title":"Impure செயற்கூறு - எளிய விளக்கம்","body":""}]},{"say":"படி ஒன்று. செயற்கூறு (function) என்பது ஒரு சிறிய இயந்திரம். உள்ளே ஒரு மதிப்பு போட்டால் வெளியே ஒரு விடை வரும்.","board":[{"kind":"diagram","title":"செயற்கூறு","body":"flowchart TD\nA[\"உள்ளீடு\"] --> B[\"செயற்கூறு\"]\nB --> C[\"விடை\"]"}]},{"say":"படி இரண்டு. வேறு ஒரு உதாரணம். ஒரு கணிப்பான் எப்போதும் இரண்டு கூட்டல் மூன்று என்றால் ஐந்து தரும். இது pure. ஆனால் உண்டியல் போல ஒரு பெட்டி, நீங்கள் காசு போடும்போது அதில் மொத்தம் கூடிக்கொண்டே போகும். அதே காசு போட்டாலும் மொத்தம் மாறும். இது impure.","board":[{"kind":"point","title":"கணிப்பான் = pure","body":""},{"kind":"point","title":"உண்டியல் = impure","body":""}]},{"say":"படி மூன்று. உண்டியலில் உள்ள மொத்தத் தொகை செயற்கூறுக்கு வெளியே உள்ள மாறி. செயற்கூறு அதை மாற்றுகிறது. இதுவே பக்க விளைவு (side effect).","board":[{"kind":"keyterm","title":"பக்க விளைவு","body":"செயற்கூறு தனக்கு வெளியே உள்ள மாறியை மாற்றுவது"}]},{"say":"படி நான்கு. பொதுவான தவறுகள். ஒன்று, impure என்றால் தவறான நிரல் என்று நினைப்பது. அது தவறு. இரண்டு, அளபுரு இருந்தால் தான் pure என்று நினைப்பது. அதுவும் தவறு. வெளி மாறியை மாற்றுகிறதா அல்லது விடை மாறுகிறதா என்று பாருங்கள்.","board":[{"kind":"warning","title":"Impure = தவறு அல்ல","body":""},{"kind":"point","title":"சோதனை: அதே உள்ளீடு, வேறு விடை? வெளி மாறி மாறுமா?","body":""}]},{"say":"படி ஐந்து. ஒரு சிறிய உதாரணம். total என்ற மாறி பூஜ்யம். add செயற்கூறு total இல் உள்ளீட்டைக் கூட்டுகிறது. இது impure.","board":[{"kind":"code","title":"உதாரணம்","body":"total := 0\nlet add x :=\n total := total + x\n return total"}]}],"practice":[{"id":"p1","type":"mcq","concept":"Impure செயற்கூறு மற்றும் பக்க விளைவு","question":"பக்க விளைவு என்றால் என்ன?","code":"","options":["செயற்கூறு தனக்கு வெளியே உள்ள மாறியை மாற்றுவது","செயற்கூறு பிழை செய்தி தருவது","செயற்கூறு தன்னை அழைப்பது","செயற்கூறுக்கு தரவு வகை எழுதுவது"],"answer":"செயற்கூறு தனக்கு வெளியே உள்ள மாறியை மாற்றுவது","keywords":[],"explanation":"செயற்கூறு வெளி மாறியை மாற்றினால் அது பக்க விளைவு ஆகும்."},{"id":"p2","type":"short","concept":"Impure செயற்கூறு மற்றும் பக்க விளைவு","question":"பக்க விளைவு எப்போதும் கேடு விளைவிக்குமா? ஏன்?","code":"","options":[],"answer":"இல்லை. பக்க விளைவு கேடு விளைவிக்கும் செயல் அல்ல, சில நேரங்களில் அது பயனுள்ளதாகும்.","keywords":["இல்லை","பயனுள்ளது","கேடு அல்ல"],"explanation":"புத்தகத்தின்படி பக்க விளைவு தீமை அல்ல, சில சமயங்களில் பயனுள்ளது."}]},{"steps":[{"say":"பரவாயில்லை! மிக அடிப்படையிலிருந்து தொடங்குவோம். உங்களுக்கு ஏற்கனவே தெரிந்ததில் இருந்து படிப்படியாகப் போவோம்.","board":[{"kind":"heading","title":"அடிப்படை: Impure செயற்கூறு","body":""}]},{"say":"உங்களுக்குத் தெரிந்தது இது. செயற்கூறு என்பது ஒரு வேலையைச் செய்யும் சிறிய நிரல் பகுதி. அதற்கு மதிப்புகளைக் கொடுக்கலாம்.","board":[{"kind":"point","title":"செயற்கூறு = சிறிய நிரல் பகுதி","body":""}]},{"say":"அதே மதிப்பைக் கொடுத்தால் எப்போதும் அதே விடை வந்தால், அது pure. அதே மதிப்புக்கு வேறு விடை வந்தால், அது impure செயற்கூறு.","board":[{"kind":"keyterm","title":"Impure செயற்கூறு","body":"அதே மதிப்புக்கு வேறு விடை தரலாம்"}]},{"say":"மிக எளிய உதாரணம். random என்ற செயற்கூறு ஒவ்வொரு முறையும் வேறு எண் தரும். அதனால் அது impure.","board":[{"kind":"example","title":"random() → 7, பிறகு 42","body":""}]},{"say":"இன்னொரு விஷயம். செயற்கூறு வெளியே உள்ள மாறியை மாற்றினால் அதற்கு பக்க விளைவு என்று பெயர். நினைவில் கொள்ளுங்கள்: அதே உள்ளீடு, வேறு விடை என்றால் impure.","board":[{"kind":"point","title":"வெளி மாறியை மாற்றுதல் = பக்க விளைவு","body":""}]}],"practice":[{"id":"p1","type":"mcq","concept":"Impure செயற்கூறு மற்றும் பக்க விளைவு","question":"அதே செயலுருபுக்கு வெவ்வேறு விடை தரும் செயற்கூறு எது?","code":"","options":["Impure செயற்கூறு","Pure செயற்கூறு","நிலையான செயற்கூறு","தற்சுழற்சி செயற்கூறு மட்டும்"],"answer":"Impure செயற்கூறு","keywords":[],"explanation":"அதே உள்ளீட்டுக்கு வேறு விடை தருவது impure செயற்கூறு."},{"id":"p2","type":"predict_output","concept":"Impure செயற்கூறு மற்றும் பக்க விளைவு","question":"y = 0. inc(2) ஐ ஒரு முறை அழைத்தால் விடை என்ன?","code":"y := 0\nlet inc (x: int): int :=\n y := y + x\n return (y)","options":[],"answer":"2","keywords":[],"explanation":"y = 0 + 2 = 2, அதுவே திருப்பி அனுப்பப்படும்."}]}],"அளபுருக்கள் மற்றும் செயலுருபுகள்":[{"steps":[{"say":"வணக்கம்! நான் குரு. இன்று அளபுருக்கள் (parameters) மற்றும் செயலுருபுகள் (arguments) என்ற இரண்டு சொற்களை ஒரு புதிய எடுத்துக்காட்டுடன் தெளிவாகப் பார்ப்போம். கவலைப்படாதீர்கள், இது எளிதுதான்.","board":[{"kind":"heading","title":"அளபுருக்கள் மற்றும் செயலுருபுகள்","body":""}]},{"say":"உங்கள் பள்ளியில் ஒரு விண்ணப்பப் படிவம் இருக்கிறது என்று நினைத்துக் கொள்ளுங்கள். படிவத்தில் பெயர் என்று ஒரு காலி இடம் இருக்கும். அந்தக் காலி இடம்தான் அளபுரு. அதில் நீங்கள் எழுதும் உங்கள் உண்மையான பெயர்தான் செயலுருபு.","board":[{"kind":"keyterm","title":"அளபுரு (parameter)","body":"செயற்கூறு வரையறையில் உள்ள மாறி. படிவத்தின் காலி இடம் போன்றது."},{"kind":"keyterm","title":"செயலுருபு (argument)","body":"செயற்கூறுக்கு அனுப்பப்படும் மதிப்பு. படிவத்தில் எழுதும் பெயர் போன்றது."}]},{"say":"இப்போது புத்தகத்தில் உள்ள செயற்கூறு (function) பார்ப்போம். இது a மற்றும் b என்ற இரண்டு அளபுருக்களைக் கொண்ட pow செயற்கூறு. இது a-வின் b மடங்கு அடுக்கைக் கணக்கிடுவதாகக் கருதப்படுகிறது.","board":[{"kind":"code","title":"செயற்கூறு வரையறை","body":"let rec pow (a: int) (b: int) : int :=\n    if b=0 then 1\n    else a * pow b (a-1)"}]},{"say":"இந்த வரையறையில் a மற்றும் b என்பவை அளபுருக்கள். செயற்கூறை அழைக்கும் போது pow 2 3 என்று எழுதினால், 2 மற்றும் 3 ஆகியவை செயலுருபுகள். 2 என்பது a-க்கும், 3 என்பது b-க்கும் செல்கிறது.","board":[{"kind":"example","title":"pow 2 3 என்ற அழைப்பில்","body":"a = 2, b = 3. இங்கு 2 மற்றும் 3 செயலுருபுகள்."}]},{"say":"நினைவில் வைக்க ஒரு எளிய வழி. வரையறையில் இருப்பது அளபுரு. அழைப்பில் இருப்பது செயலுருபு. தேர்வில் இந்த வேறுபாட்டைக் கேட்பார்கள். இது முக்கியம்.","board":[{"kind":"diagram","title":"அழைப்பு மற்றும் வரையறை","body":"flowchart TD\nA[\"செயலுருபு 2, 3\"] --> B[\"அழைப்பு pow 2 3\"]\nB --> C[\"அளபுரு a, b\"]\nC --> D[\"வரையறைக்குள் பயன்பாடு\"]"}]}],"practice":[{"id":"p1","type":"mcq","concept":"அளபுருக்கள் மற்றும் செயலுருபுகள்","question":"செயற்கூறு வரையறையில் உள்ள மாறிகள் எவ்வாறு அழைக்கப்படுகின்றன?","code":"","options":["அளபுருக்கள்","செயலுருபுகள்","துணை நிரல்கள்","இடைமுகம்"],"answer":"அளபுருக்கள்","keywords":[],"explanation":"செயற்கூறு வரையறையில் உள்ள மாறிகள் அளபுருக்கள் (parameters) ஆகும்."},{"id":"p2","type":"mcq","concept":"அளபுருக்கள் மற்றும் செயலுருபுகள்","question":"pow 2 3 என்ற அழைப்பில் 2 மற்றும் 3 என்பவை என்ன?","code":"let rec pow a b := ...","options":["செயலுருபுகள்","அளபுருக்கள்","செயற்கூறின் பெயர்கள்","சிறப்புச் சொற்கள்"],"answer":"செயலுருபுகள்","keywords":[],"explanation":"அழைக்கும் போது அனுப்பப்படும் மதிப்புகள் செயலுருபுகள் (arguments) ஆகும்."}]},{"steps":[{"say":"சரி, இன்னும் எளிமையாகப் படிப்படியாகப் பார்ப்போம். முதலில் ஒரு தேநீர்க் கடை எடுத்துக்காட்டு.","board":[{"kind":"heading","title":"எளிய வழியில் மீண்டும்","body":""}]},{"say":"தேநீர்க் கடையில் ஒரு டம்ளர் இருக்கிறது. அந்த டம்ளர் காலியாக இருக்கும். அதுதான் அளபுரு. அதில் ஊற்றப்படும் தேநீர்தான் செயலுருபு. டம்ளர் வரையறையில் இருக்கும். தேநீர் அழைக்கும் போது வரும்.","board":[{"kind":"point","title":"டம்ளர் = அளபுரு (parameter)","body":""},{"kind":"point","title":"தேநீர் = செயலுருபு (argument)","body":""}]},{"say":"இப்போது இதே கருத்தை ஒரு சிறிய செயற்கூறில் பார்ப்போம். square என்ற செயற்கூறு x என்ற ஒரு எண்ணைப் பெற்று அதை அதே எண்ணால் பெருக்குகிறது.","board":[{"kind":"code","title":"square செயற்கூறு","body":"let square x:=\n return: x * x"}]},{"say":"இங்கே x என்பது அளபுரு. நாம் square 5 என்று அழைத்தால், 5 என்பது செயலுருபு. x-க்கு 5 கிடைக்கும். விடை 25.","board":[{"kind":"example","title":"square 5","body":"x = 5, விடை 25"}]},{"say":"மாணவர்கள் செய்யும் பொதுவான தவறைக் கவனியுங்கள். சிலர் இரண்டையும் மாற்றிச் சொல்வார்கள். வரையறையில் உள்ள மாறி அளபுரு. அனுப்பப்படும் மதிப்பு செயலுருபு. இரண்டையும் ஒன்றாகக் குழப்ப வேண்டாம்.","board":[{"kind":"warning","title":"தவறு: x என்பதைச் செயலுருபு என்பது","body":"x அளபுரு. 5 செயலுருபு."}]}],"practice":[{"id":"p1","type":"mcq","concept":"அளபுருக்கள் மற்றும் செயலுருபுகள்","question":"square 7 என்று அழைக்கும் போது, 7 என்பது என்ன?","code":"let square x:=\n return: x * x","options":["செயலுருபு","அளபுரு","செயற்கூறின் பெயர்","வெளியீடு வகை"],"answer":"செயலுருபு","keywords":[],"explanation":"அழைப்பில் அனுப்பப்படும் மதிப்பு 7, அது செயலுருபு ஆகும்."},{"id":"p2","type":"short","concept":"அளபுருக்கள் மற்றும் செயலுருபுகள்","question":"கொடுக்கப்பட்ட வரையறையில் அளபுரு எது?","code":"let square x:=\n return: x * x","options":[],"answer":"x என்பது அளபுரு, ஏனெனில் அது செயற்கூறு வரையறையில் உள்ள மாறி.","keywords":["x","வரையறையில்","மாறி"],"explanation":"வரையறையில் உள்ள மாறி x ஆகும், ஆகவே அதுவே அளபுரு."}]},{"steps":[{"say":"பரவாயில்லை, மிக அடிப்படையிலிருந்து தொடங்குவோம். நீங்கள் ஏற்கனவே கணிதத்தில் f of x என்று படித்திருக்கிறீர்கள். அதிலிருந்து தொடங்குவோம்.","board":[{"kind":"heading","title":"அடிப்படையிலிருந்து","body":""}]},{"say":"கணிதத்தில் f of x சமம் x கூட்டல் 1 என்று எழுதுவோம். இங்கே x என்பது அளபுரு. f of 4 என்று எழுதினால் 4 என்பது செயலுருபு. விடை 5.","board":[{"kind":"example","title":"f(x) = x + 1","body":"f(4): x = 4, விடை 5"}]},{"say":"இரண்டு சொற்களையும் ஒரே வாக்கியத்தில் நினைவில் வைப்போம். அளபுரு என்பது பெயர். செயலுருபு என்பது மதிப்பு.","board":[{"kind":"point","title":"அளபுரு = பெயர் (வரையறையில்)","body":""},{"kind":"point","title":"செயலுருபு = மதிப்பு (அழைப்பில்)","body":""}]},{"say":"புத்தகத்தில் gcd செயற்கூறு a மற்றும் b என்ற அளபுருக்களைக் கொண்டுள்ளது. gcd 13 27 என்று அழைத்தால் 13 மற்றும் 27 செயலுருபுகள். தேர்வில் இதைக் கேட்பார்கள், எனவே நன்றாகப் பழகுங்கள்.","board":[{"kind":"code","title":"gcd","body":"let rec gcd a b :=\n if b <> 0 then gcd b (a mod b)\n else\n return a"}]}],"practice":[{"id":"p1","type":"mcq","concept":"அளபுருக்கள் மற்றும் செயலுருபுகள்","question":"gcd 13 27 என்ற அழைப்பில் 13 மற்றும் 27 என்பவை என்ன?","code":"let rec gcd a b := ...","options":["செயலுருபுகள்","அளபுருக்கள்","மாறிகளின் பெயர்கள்","தரவு வகைகள்"],"answer":"செயலுருபுகள்","keywords":[],"explanation":"அழைப்பில் அனுப்பப்படும் மதிப்புகள் செயலுருபுகள் ஆகும்."},{"id":"p2","type":"short","concept":"அளபுருக்கள் மற்றும் செயலுருபுகள்","question":"gcd செயற்கூறின் அளபுருக்கள் எவை?","code":"let rec gcd a b :=\n if b <> 0 then gcd b (a mod b)\n else\n return a","options":[],"answer":"a மற்றும் b ஆகியவை gcd செயற்கூறின் அளபுருக்கள்.","keywords":["a","b","அளபுருக்கள்"],"explanation":"செயற்கூறு பெயருக்குப் பின் எழுதப்பட்டுள்ள மாறிகள் a மற்றும் b ஆகும்."}]}]}};
